(303948,33772,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, olyan ... nyomja a fekvőtámaszokat, pörgős vibe, komolyan.'::text,'gyorsan'::text,'gyorsan'::text,'leggyorsabban'::text,'Tesó, olyan gyorsan nyomja a fekvőtámaszokat, pörgős vibe, komolyan.'::text),
(312231,34693,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unmöglich! Dieses Wasser ... den ganzen Himmel spiegeln! Ich bin total geschockt!'::text,'kann'::text,'kann'::text,'kann'::text,'Unmöglich! Dieses Wasser kann den ganzen Himmel spiegeln! Ich bin total geschockt!'::text),
(312235,34693,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неможливо! Ця вода ... відбивати все небо! Я в повному шоці!'::text,'може'::text,'може'::text,'може'::text,'Неможливо! Ця вода може відбивати все небо! Я в повному шоці!'::text),
(312234,34693,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Imposible! ¡Esta agua ... reflejar todo el cielo! ¡Estoy completamente en shock!'::text,'puede'::text,'puede'::text,'puede'::text,'¡Imposible! ¡Esta agua puede reflejar todo el cielo! ¡Estoy completamente en shock!'::text),
(312233,34693,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impossible ! Cette eau ... refléter tout le ciel ! Je suis complètement choqué !'::text,'peut'::text,'peut'::text,'peut'::text,'Impossible ! Cette eau peut refléter tout le ciel ! Je suis complètement choqué !'::text),
(312236,34693,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İmkânsız! Bu su bütün gökyüzünü ...! Resmen şoktayım!'::text,'yansıtabilir'::text,'yansıtabilir'::text,'yansıtabilir'::text,'İmkânsız! Bu su bütün gökyüzünü yansıtabilir! Resmen şoktayım!'::text),
(312237,34693,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lehetetlen! Ez a víz ... az egész eget! Teljesen sokkban vagyok!'::text,'tükrözheti'::text,'tükrözheti'::text,'tükrözheti'::text,'Lehetetlen! Ez a víz tükrözheti az egész eget! Teljesen sokkban vagyok!'::text),
(312240,34694,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat gesagt, dass das Wasser heute Nacht auch die Sterne ...'::text,'spiegeln wird'::text,'spiegelnd'::text,'spiegelte'::text,'Hör zu, sie hat gesagt, dass das Wasser heute Nacht auch die Sterne spiegeln wird.'::text),
(312244,34694,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що вода сьогодні вночі ... і зірки.'::text,'відбиватиме'::text,'відбиваючи'::text,'відбивала'::text,'Слухай, вона сказала, що вода сьогодні вночі відбиватиме і зірки.'::text),
(312243,34694,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dijo que el agua ... también las estrellas esta noche.'::text,'reflejará'::text,'reflejando'::text,'reflejó'::text,'Oye, dijo que el agua reflejará también las estrellas esta noche.'::text),
(312242,34694,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit que l''eau ... aussi les étoiles ce soir.'::text,'reflétera'::text,'reflétant'::text,'a reflété'::text,'Écoute, elle a dit que l''eau reflétera aussi les étoiles ce soir.'::text),
(312245,34694,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, dedi ki su bu gece yıldızları da ...'::text,'yansıtacak'::text,'yansıtarak'::text,'yansıttı'::text,'Dinle, dedi ki su bu gece yıldızları da yansıtacak.'::text),
(312246,34694,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy ma este a víz a csillagokat is ...'::text,'tükrözni fogja'::text,'tükrözve'::text,'tükrözte'::text,'Figyelj, azt mondta, hogy ma este a víz a csillagokat is tükrözni fogja.'::text),
(312258,34696,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, kein Wind, das Wasser ist wie Glas. Es ... alles spiegeln, echt.'::text,'wird'::text,'wird'::text,NULL::text,'Alter, kein Wind, das Wasser ist wie Glas. Es wird alles spiegeln, echt.'::text),
(312262,34696,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вітру нуль, вода як скло. Вона ... все, чесно.'::text,'збирається відбивати'::text,'відбиватиме'::text,NULL::text,'Бро, вітру нуль, вода як скло. Вона збирається відбивати все, чесно.'::text),
(312261,34696,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, cero viento, el agua está como un cristal. ... todo, en serio.'::text,'Va a reflejar'::text,'Reflejará'::text,NULL::text,'Tío, cero viento, el agua está como un cristal. Va a reflejar todo, en serio.'::text),
(312260,34696,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, pas de vent, l''eau est comme du verre. Elle ... tout, sérieux.'::text,'va refléter'::text,'reflétera'::text,NULL::text,'Frérot, pas de vent, l''eau est comme du verre. Elle va refléter tout, sérieux.'::text),
(312263,34696,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, rüzgâr yok, su cam gibi. Her şeyi ..., cidden.'::text,'yansıtacak'::text,'yansıtacak'::text,NULL::text,'Kanka, rüzgâr yok, su cam gibi. Her şeyi yansıtacak, cidden.'::text),
(312264,34696,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, semmi szél, a víz olyan, mint az üveg. Mindent ..., komolyan.'::text,'tükrözni fog'::text,'tükrözni fog'::text,NULL::text,'Tesó, semmi szél, a víz olyan, mint az üveg. Mindent tükrözni fog, komolyan.'::text),
(312267,34697,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Alter, Parkregel: Die Leute ... das Wasser sauber halten, damit es spiegelt.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Nee, Alter, Parkregel: Die Leute müssen das Wasser sauber halten, damit es spiegelt.'::text),
(312271,34697,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, правило парку: люди ... тримати воду чистою, щоб вона відбивала.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Не, бро, правило парку: люди мають тримати воду чистою, щоб вона відбивала.'::text),
(312270,34697,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, norma del parque: la gente ... mantener el agua limpia para que refleje.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Qué va, tío, norma del parque: la gente tiene que mantener el agua limpia para que refleje.'::text),
(312269,34697,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, frérot, règle du parc : les gens ... garder l''eau propre pour qu''elle reflète.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Non, frérot, règle du parc : les gens doivent garder l''eau propre pour qu''elle reflète.'::text),
(312272,34697,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, park kuralı: insanlar suyu temiz ... ki yansıtsın.'::text,'tutmak zorunda'::text,'tutmalı'::text,'tutmalı'::text,'Yok kanka, park kuralı: insanlar suyu temiz tutmak zorunda ki yansıtsın.'::text),
(312273,34697,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, parkszabály: az embereknek tisztán ... tartaniuk a vizet, hogy tükrözzön.'::text,'kell'::text,'kell'::text,'kellene'::text,'Á, tesó, parkszabály: az embereknek tisztán kell tartaniuk a vizet, hogy tükrözzön.'::text),
(312276,34698,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Q2-Roadmap: Ihr ... dort filmen, wo das Wasser den Himmel spiegelt.'::text,'solltet'::text,'solltet'::text,'solltet'::text,'Q2-Roadmap: Ihr solltet dort filmen, wo das Wasser den Himmel spiegelt.'::text),
(312280,34698,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Роадмап на Q2: ви ... знімати там, де вода відбиває небо.'::text,'мали б'::text,'мали б'::text,'мали б'::text,'Роадмап на Q2: ви мали б знімати там, де вода відбиває небо.'::text),
(312279,34698,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roadmap del Q2: vosotros ... grabar donde el agua refleja el cielo.'::text,'deberíais'::text,'deberíais'::text,'deberíais'::text,'Roadmap del Q2: vosotros deberíais grabar donde el agua refleja el cielo.'::text),
(312278,34698,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roadmap du Q2 : vous ... filmer là où l''eau reflète le ciel.'::text,'devriez'::text,'devriez'::text,'devriez'::text,'Roadmap du Q2 : vous devriez filmer là où l''eau reflète le ciel.'::text),
(312281,34698,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Q2 yol haritası: suyun gökyüzünü yansıttığı yerde ...'::text,'çekim yapmalısınız'::text,'çekim yapmalısınız'::text,'çekim yapmalısınız'::text,'Q2 yol haritası: suyun gökyüzünü yansıttığı yerde çekim yapmalısınız.'::text),
(312282,34698,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Q2-es roadmap: ott ... forgatnotok, ahol a víz tükrözi az eget.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Q2-es roadmap: ott kellene forgatnotok, ahol a víz tükrözi az eget.'::text),
(312285,34699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wasser ist ganz still, ... spiegelt es den ganzen Himmel.'::text,'also'::text,'aber'::text,'weil'::text,'Das Wasser ist ganz still, also spiegelt es den ganzen Himmel.'::text),
(312289,34699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вода дуже спокійна, ... вона відбиває все небо.'::text,'тому'::text,'але'::text,'бо'::text,'Вода дуже спокійна, тому вона відбиває все небо.'::text),
(312288,34699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agua está muy quieta, ... refleja todo el cielo.'::text,'así que'::text,'pero'::text,'porque'::text,'El agua está muy quieta, así que refleja todo el cielo.'::text),
(312287,34699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''eau est très calme, ... elle reflète tout le ciel.'::text,'donc'::text,'mais'::text,'parce que'::text,'L''eau est très calme, donc elle reflète tout le ciel.'::text),
(312290,34699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su çok durgun, ... bütün gökyüzünü yansıtıyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Su çok durgun, bu yüzden bütün gökyüzünü yansıtıyor.'::text),
(312291,34699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A víz nagyon nyugodt, ... az egész eget tükrözi.'::text,'ezért'::text,'de'::text,'mert'::text,'A víz nagyon nyugodt, ezért az egész eget tükrözi.'::text),
(311304,34590,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... sie das ganze Essen in wenigen Minuten in den Kühlschrank.'::text,'packte'::text,'packte'::text,'packt'::text,'Mädel, anscheinend packte sie das ganze Essen in wenigen Minuten in den Kühlschrank.'::text),
(311308,34590,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... всю ту їжу в холодильник за кілька хвилин.'::text,'поклала'::text,'поклала'::text,'кладе'::text,'Подруго, кажуть, вона поклала всю ту їжу в холодильник за кілька хвилин.'::text),
(311307,34590,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ella ... toda esa comida en la nevera en minutos.'::text,'metió'::text,'metió'::text,'mete'::text,'Tía, al parecer ella metió toda esa comida en la nevera en minutos.'::text),
(311306,34590,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... toute cette bouffe dans le frigo en quelques minutes.'::text,'a mis'::text,'a mis'::text,'met'::text,'Meuf, apparemment elle a mis toute cette bouffe dans le frigo en quelques minutes.'::text),
(311309,34590,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre bütün o yiyecekleri birkaç dakikada buzdolabına ...'::text,'koydu'::text,'koydu'::text,'koyar'::text,'Kızım, duyduğuma göre bütün o yiyecekleri birkaç dakikada buzdolabına koydu.'::text),
(311310,34590,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag percek alatt ... az összes kaját a hűtőbe.'::text,'betette'::text,'betette'::text,'beteszi'::text,'Csajszi, állítólag percek alatt betette az összes kaját a hűtőbe.'::text),
(311313,34591,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, gestern ... sie mega viel Essen in diesen leeren Kühlschrank, ohne Witz.'::text,'packte'::text,'packt'::text,NULL::text,'Alter, gestern packte sie mega viel Essen in diesen leeren Kühlschrank, ohne Witz.'::text),
(311317,34591,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вчора вона ... купу їжі в той порожній холодильник, чесно.'::text,'поклала'::text,'кладе'::text,NULL::text,'Бро, вчора вона поклала купу їжі в той порожній холодильник, чесно.'::text),
(311316,34591,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ayer ella ... un montón de comida en esa nevera vacía, en serio.'::text,'metió'::text,'mete'::text,NULL::text,'Tío, ayer ella metió un montón de comida en esa nevera vacía, en serio.'::text),
(311315,34591,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, hier elle ... grave de bouffe dans ce frigo vide, sans mentir.'::text,'a mis'::text,'met'::text,NULL::text,'Frérot, hier elle a mis grave de bouffe dans ce frigo vide, sans mentir.'::text),
(311318,34591,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dün o boş buzdolabına bir ton yiyecek ..., cidden.'::text,'koydu'::text,'koyar'::text,NULL::text,'Kanka, dün o boş buzdolabına bir ton yiyecek koydu, cidden.'::text),
(311319,34591,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, tegnap egy csomó kaját ... abba az üres hűtőbe, komolyan.'::text,'pakolt'::text,'pakol'::text,NULL::text,'Tesó, tegnap egy csomó kaját pakolt abba az üres hűtőbe, komolyan.'::text),
(311322,34592,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie ... gerade jetzt einen Apfel in den Kühlschrank, Mann.'::text,'legt'::text,'legt'::text,'legt'::text,'Yo, sie legt gerade jetzt einen Apfel in den Kühlschrank, Mann.'::text),
(311326,34592,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона саме зараз ... яблуко в холодильник, чувак.'::text,'кладе'::text,'кладе'::text,'кладе'::text,'Йо, вона саме зараз кладе яблуко в холодильник, чувак.'::text),
(311325,34592,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ella ... una manzana en la nevera ahora mismo, tío.'::text,'está metiendo'::text,'mete'::text,'está metiendo'::text,'Oye, ella está metiendo una manzana en la nevera ahora mismo, tío.'::text),
(311324,34592,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, elle ... une pomme dans le frigo en ce moment, mec.'::text,'est en train de mettre'::text,'met'::text,'est en train de mettre'::text,'Yo, elle est en train de mettre une pomme dans le frigo en ce moment, mec.'::text),
(311327,34592,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, şu an buzdolabına bir elma ..., dostum.'::text,'koyuyor'::text,'koyar'::text,'koyuyor'::text,'Kanka, şu an buzdolabına bir elma koyuyor, dostum.'::text),
(311328,34592,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, most épp ... egy almát a hűtőbe, haver.'::text,'tesz'::text,'tesz'::text,'tesz'::text,'Figyu, most épp tesz egy almát a hűtőbe, haver.'::text),
(311331,34593,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestandsupdate: Normalerweise kauft sie wenig, aber heute ... sie 20 Artikel in den Kühlschrank.'::text,'legt'::text,'legt'::text,NULL::text,'Bestandsupdate: Normalerweise kauft sie wenig, aber heute legt sie 20 Artikel in den Kühlschrank.'::text),
(311335,34593,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оновлення запасів: зазвичай вона купує мало, але сьогодні вона ... в холодильник 20 позицій.'::text,'кладе'::text,'кладе'::text,NULL::text,'Оновлення запасів: зазвичай вона купує мало, але сьогодні вона кладе в холодильник 20 позицій.'::text),
(311334,34593,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualización de stock: normalmente compra poco, pero hoy ella ... 20 artículos en la nevera.'::text,'está metiendo'::text,'mete'::text,NULL::text,'Actualización de stock: normalmente compra poco, pero hoy ella está metiendo 20 artículos en la nevera.'::text),
(311333,34593,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Point stock : d''habitude elle achète peu, mais aujourd''hui elle ... 20 articles dans le frigo.'::text,'est en train de mettre'::text,'met'::text,NULL::text,'Point stock : d''habitude elle achète peu, mais aujourd''hui elle est en train de mettre 20 articles dans le frigo.'::text),
(311336,34593,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stok güncellemesi: genelde az alır ama bugün buzdolabına 20 ürün ...'::text,'koyuyor'::text,'koyar'::text,NULL::text,'Stok güncellemesi: genelde az alır ama bugün buzdolabına 20 ürün koyuyor.'::text),
(311337,34593,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Készletfrissítés: általában keveset vesz, de ma 20 tételt ... a hűtőbe.'::text,'tesz'::text,'tesz'::text,NULL::text,'Készletfrissítés: általában keveset vesz, de ma 20 tételt tesz a hűtőbe.'::text),
(311340,34594,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Kühlschrank ist für Essen, also ... sie morgen Essen hineinlegen.'::text,'wird'::text,'legt'::text,'legte'::text,'Ein Kühlschrank ist für Essen, also wird sie morgen Essen hineinlegen.'::text),
(311344,34594,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Холодильник — для їжі, тож завтра вона ... в нього їжу.'::text,'покладе'::text,'кладе'::text,'поклала'::text,'Холодильник — для їжі, тож завтра вона покладе в нього їжу.'::text),
(311343,34594,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una nevera es para comida, así que mañana ella ... comida dentro.'::text,'meterá'::text,'mete'::text,'metió'::text,'Una nevera es para comida, así que mañana ella meterá comida dentro.'::text),
(311342,34594,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un frigo, c''est pour la nourriture, donc demain elle ... de la nourriture dedans.'::text,'mettra'::text,'met'::text,'a mis'::text,'Un frigo, c''est pour la nourriture, donc demain elle mettra de la nourriture dedans.'::text),
(311345,34594,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buzdolabı yiyecek içindir, yani yarın içine yiyecek ...'::text,'koyacak'::text,'koyar'::text,'koydu'::text,'Buzdolabı yiyecek içindir, yani yarın içine yiyecek koyacak.'::text),
(311346,34594,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hűtő kajának való, úgyhogy holnap kaját ... bele.'::text,'fog tenni'::text,'tesz'::text,'tett'::text,'A hűtő kajának való, úgyhogy holnap kaját fog tenni bele.'::text),
(311349,34595,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kühlschrank ist leer. Sie ... etwas Essen hineinlegen.'::text,'wird'::text,'wird'::text,'werden'::text,'Der Kühlschrank ist leer. Sie wird etwas Essen hineinlegen.'::text),
(311353,34595,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Холодильник порожній. Вона ... покласти в нього трохи їжі.'::text,'збирається'::text,'збирається'::text,'збираються'::text,'Холодильник порожній. Вона збирається покласти в нього трохи їжі.'::text),
(311352,34595,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nevera está vacía. Ella ... meter algo de comida dentro.'::text,'va a'::text,'va a'::text,'van a'::text,'La nevera está vacía. Ella va a meter algo de comida dentro.'::text),
(311351,34595,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le frigo est vide. Elle ... mettre un peu de nourriture dedans.'::text,'va'::text,'va'::text,'vont'::text,'Le frigo est vide. Elle va mettre un peu de nourriture dedans.'::text),
(311354,34595,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buzdolabı boş. İçine biraz yiyecek ...'::text,'koyacak'::text,'koyacak'::text,'koyacaklar'::text,'Buzdolabı boş. İçine biraz yiyecek koyacak.'::text),
(311355,34595,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hűtő üres. Egy kis kaját ... tenni bele.'::text,'fog'::text,'fog'::text,'fognak'::text,'A hűtő üres. Egy kis kaját fog tenni bele.'::text),
(301143,33461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das Zimmer, also ist das Zimmer jetzt besser.'::text,'verbesserten'::text,'verbessern'::text,'verbesserten'::text,'Sie verbesserten das Zimmer, also ist das Zimmer jetzt besser.'::text),
(301147,33461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... кімнату, тож тепер кімната краща.'::text,'покращили'::text,'покращують'::text,'покращили'::text,'Вони покращили кімнату, тож тепер кімната краща.'::text),
(301146,33461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... la habitación, así que ahora la habitación está mejor.'::text,'mejoraron'::text,'mejoran'::text,'mejoraron'::text,'Ellos mejoraron la habitación, así que ahora la habitación está mejor.'::text),
(301145,33461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... la pièce, donc maintenant la pièce est mieux.'::text,'ont amélioré'::text,'améliorent'::text,'ont amélioré'::text,'Ils ont amélioré la pièce, donc maintenant la pièce est mieux.'::text),
(301148,33461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Odayı ..., yani oda artık daha iyi.'::text,'iyileştirdiler'::text,'iyileştirirler'::text,'iyileştirdiler'::text,'Odayı iyileştirdiler, yani oda artık daha iyi.'::text),
(301149,33461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a szobát, úgyhogy most a szoba jobb.'::text,'Feljavították'::text,'Feljavítják'::text,'Feljavították'::text,'Feljavították a szobát, úgyhogy most a szoba jobb.'::text),
(301152,33462,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise putzen sie nur, aber gestern ... sie diese totale Katastrophe!'::text,'verbesserten'::text,'verbessern'::text,NULL::text,'Normalerweise putzen sie nur, aber gestern verbesserten sie diese totale Katastrophe!'::text),
(301156,33462,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вони просто прибирають, але вчора вони ... цю повну катастрофу!'::text,'покращили'::text,'покращують'::text,NULL::text,'Зазвичай вони просто прибирають, але вчора вони покращили цю повну катастрофу!'::text),
(301155,33462,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Normalmente solo limpian, pero ayer ellos ... este desastre total!'::text,'mejoraron'::text,'mejoran'::text,NULL::text,'¡Normalmente solo limpian, pero ayer ellos mejoraron este desastre total!'::text),
(301154,33462,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, ils font juste le ménage, mais hier ils ... cette catastrophe totale !'::text,'ont amélioré'::text,'améliorent'::text,NULL::text,'D''habitude, ils font juste le ménage, mais hier ils ont amélioré cette catastrophe totale !'::text),
(301157,33462,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde sadece temizlik yaparlar ama dün bu tam felaketi ...!'::text,'iyileştirdiler'::text,'iyileştirirler'::text,NULL::text,'Genelde sadece temizlik yaparlar ama dün bu tam felaketi iyileştirdiler!'::text),
(301158,33462,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában csak takarítanak, de tegnap ... ezt a totális katasztrófát!'::text,'feljavították'::text,'feljavítják'::text,NULL::text,'Általában csak takarítanak, de tegnap feljavították ezt a totális katasztrófát!'::text),
(301161,33463,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... dieses schreckliche Zimmer! Schluss mit der Katastrophe!'::text,'verbessern'::text,'verbessern'::text,'verbessern'::text,'Sie verbessern dieses schreckliche Zimmer! Schluss mit der Katastrophe!'::text),
(301165,33463,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... цю жахливу кімнату! Кінець катастрофі!'::text,'покращують'::text,'покращують'::text,'покращують'::text,'Вони покращують цю жахливу кімнату! Кінець катастрофі!'::text),
(301164,33463,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... esta habitación horrible! ¡Se acabó el desastre!'::text,'están mejorando'::text,'mejoran'::text,'están mejorando'::text,'¡Ellos están mejorando esta habitación horrible! ¡Se acabó el desastre!'::text),
(301163,33463,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... cette pièce horrible ! Fini la catastrophe !'::text,'sont en train d''améliorer'::text,'améliorent'::text,'sont en train d''améliorer'::text,'Ils sont en train d''améliorer cette pièce horrible ! Fini la catastrophe !'::text),
(301166,33463,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu berbat odayı ...! Felaket bitti!'::text,'iyileştiriyorlar'::text,'iyileştirirler'::text,'iyileştiriyorlar'::text,'Bu berbat odayı iyileştiriyorlar! Felaket bitti!'::text),
(301167,33463,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ezt a borzalmas szobát! Vége a katasztrófának!'::text,'Feljavítják'::text,'Feljavítják'::text,'Feljavítják'::text,'Feljavítják ezt a borzalmas szobát! Vége a katasztrófának!'::text),
(301170,33464,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise arbeiten sie in Büros, aber diese Woche ... sie ein altes Zimmer.'::text,'verbessern'::text,'verbessern'::text,NULL::text,'Normalerweise arbeiten sie in Büros, aber diese Woche verbessern sie ein altes Zimmer.'::text),
(301174,33464,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вони працюють в офісах, але цього тижня вони ... стару кімнату.'::text,'покращують'::text,'покращують'::text,NULL::text,'Зазвичай вони працюють в офісах, але цього тижня вони покращують стару кімнату.'::text),
(301173,33464,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente trabajan en oficinas, pero esta semana ellos ... una habitación vieja.'::text,'están mejorando'::text,'mejoran'::text,NULL::text,'Normalmente trabajan en oficinas, pero esta semana ellos están mejorando una habitación vieja.'::text),
(301172,33464,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, ils travaillent dans des bureaux, mais cette semaine ils ... une vieille pièce.'::text,'sont en train d''améliorer'::text,'améliorent'::text,NULL::text,'D''habitude, ils travaillent dans des bureaux, mais cette semaine ils sont en train d''améliorer une vieille pièce.'::text),
(301175,33464,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde ofislerde çalışırlar ama bu hafta eski bir odayı ...'::text,'iyileştiriyorlar'::text,'iyileştirirler'::text,NULL::text,'Genelde ofislerde çalışırlar ama bu hafta eski bir odayı iyileştiriyorlar.'::text),
(301176,33464,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában irodákban dolgoznak, de ezen a héten egy régi szobát ...'::text,'javítanak fel'::text,'javítanak fel'::text,NULL::text,'Általában irodákban dolgoznak, de ezen a héten egy régi szobát javítanak fel.'::text),
(301179,33465,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich glaube, dass neue Regale das Zimmer sehr ...'::text,'verbessern werden'::text,'verbessert'::text,'verbesserten'::text,'Ich glaube, dass neue Regale das Zimmer sehr verbessern werden.'::text),
(301183,33465,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Думаю, нові полиці дуже ... кімнату.'::text,'покращать'::text,'покращує'::text,'покращили'::text,'Думаю, нові полиці дуже покращать кімнату.'::text),
(301182,33465,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Creo que unas estanterías nuevas ... mucho la habitación.'::text,'mejorarán'::text,'mejora'::text,'mejoraron'::text,'Creo que unas estanterías nuevas mejorarán mucho la habitación.'::text),
(301181,33465,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je pense que de nouvelles étagères ... beaucoup la pièce.'::text,'amélioreront'::text,'améliore'::text,'ont amélioré'::text,'Je pense que de nouvelles étagères amélioreront beaucoup la pièce.'::text),
(301184,33465,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence yeni raflar odayı çok ...'::text,'iyileştirecek'::text,'iyileştirir'::text,'iyileştirdi'::text,'Bence yeni raflar odayı çok iyileştirecek.'::text),
(301185,33465,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szerintem az új polcok sokat ... a szobán.'::text,'fognak javítani'::text,'javít'::text,'javítottak'::text,'Szerintem az új polcok sokat fognak javítani a szobán.'::text),
(301197,33467,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, diese Wand ist meh. Okay, ich ... sie jetzt sofort aufwerten, Alter.'::text,'werde'::text,'werde'::text,NULL::text,'Nee, diese Wand ist meh. Okay, ich werde sie jetzt sofort aufwerten, Alter.'::text),
(301201,33467,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, ця стіна так собі. Окей, я ... її прямо зараз, бро.'::text,'покращу'::text,'збираюся покращити'::text,NULL::text,'Не, ця стіна так собі. Окей, я покращу її прямо зараз, бро.'::text),
(301200,33467,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, esta pared es muy normalita. Vale, la ... ahora mismo, tío.'::text,'mejoraré'::text,'voy a mejorar'::text,NULL::text,'Nah, esta pared es muy normalita. Vale, la mejoraré ahora mismo, tío.'::text),
(301199,33467,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, ce mur est bof. Ok, je ... tout de suite, frérot.'::text,'l''améliorerai'::text,'vais l''améliorer'::text,NULL::text,'Nan, ce mur est bof. Ok, je l''améliorerai tout de suite, frérot.'::text),
(301202,33467,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, bu duvar vasat. Tamam, hemen şimdi ..., kanka.'::text,'iyileştireceğim'::text,'iyileştireceğim'::text,NULL::text,'Yok, bu duvar vasat. Tamam, hemen şimdi iyileştireceğim, kanka.'::text),
