(319296,35478,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Familie wartet am Bahnhof auf ... Tochter.'::text,'ihre'::text,'ihre'::text,'ihre'::text,'Die Familie wartet am Bahnhof auf ihre Tochter.'::text),
