(325643,36183,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme sur le toit ... un gilet jaune.'::text,'a'::text,'ont'::text,'a'::text,'L''homme sur le toit a un gilet jaune.'::text),
(325646,36183,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çatıdaki adamın sarı bir yeleği ...'::text,'var'::text,'var'::text,'var'::text,'Çatıdaki adamın sarı bir yeleği var.'::text),
(325647,36183,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tetőn álló férfinak ... egy sárga mellénye.'::text,'van'::text,'van'::text,'van'::text,'A tetőn álló férfinak van egy sárga mellénye.'::text),
(325650,36184,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese gelbe Weste ist neu. Er hat ... zu Hause.'::text,'3 alte Westen'::text,'3 alte Weste'::text,'3 alte Westen'::text,'Diese gelbe Weste ist neu. Er hat 3 alte Westen zu Hause.'::text),
(325654,36184,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей жовтий жилет новий. Удома в нього є ...'::text,'3 старі жилети'::text,'3 старий жилет'::text,'3 старі жилети'::text,'Цей жовтий жилет новий. Удома в нього є 3 старі жилети.'::text),
(325653,36184,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este chaleco amarillo es nuevo. Él tiene ... en casa.'::text,'3 chalecos viejos'::text,'3 chaleco viejo'::text,'3 chalecos viejos'::text,'Este chaleco amarillo es nuevo. Él tiene 3 chalecos viejos en casa.'::text),
(325652,36184,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce gilet jaune est neuf. Il a ... à la maison.'::text,'3 vieux gilets'::text,'3 vieux gilet'::text,'3 vieux gilets'::text,'Ce gilet jaune est neuf. Il a 3 vieux gilets à la maison.'::text),
(325655,36184,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sarı yelek yeni. Evde ... var.'::text,'3 eski yeleği'::text,'3 eski yeleği'::text,'3 eski yeleği'::text,'Bu sarı yelek yeni. Evde 3 eski yeleği var.'::text),
(325656,36184,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a sárga mellény új. Otthon van ...'::text,'3 régi mellénye'::text,'3 régi mellénye'::text,'3 régi mellénye'::text,'Ez a sárga mellény új. Otthon van 3 régi mellénye.'::text),
(325668,36186,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ... gelbe Weste ist so grell, ich brauch gleich eine Sonnenbrille.'::text,'diese'::text,'diese'::text,'jene'::text,'Alter, diese gelbe Weste ist so grell, ich brauch gleich eine Sonnenbrille.'::text),
(325672,36186,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, ... жовтий жилет такий яскравий, треба буде сонцезахисні окуляри.'::text,'цей'::text,'ці'::text,'ті'::text,'Чувак, цей жовтий жилет такий яскравий, треба буде сонцезахисні окуляри.'::text),
(325671,36186,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... chaleco amarillo es tan chillón que voy a necesitar gafas de sol.'::text,'este'::text,'estos'::text,'esos'::text,'Tío, este chaleco amarillo es tan chillón que voy a necesitar gafas de sol.'::text),
(325670,36186,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ... gilet jaune est tellement flashy, il va me falloir des lunettes de soleil.'::text,'ce'::text,'ces'::text,'ces'::text,'Mec, ce gilet jaune est tellement flashy, il va me falloir des lunettes de soleil.'::text),
(325673,36186,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... sarı yelek o kadar parlak ki güneş gözlüğü lazım olacak.'::text,'bu'::text,'bu'::text,'şu'::text,'Kanka, bu sarı yelek o kadar parlak ki güneş gözlüğü lazım olacak.'::text),
(325674,36186,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... a sárga mellény annyira rikító, napszemüveg kell majd.'::text,'ez'::text,'ezek'::text,'azok'::text,'Tesó, ez a sárga mellény annyira rikító, napszemüveg kell majd.'::text),
(325677,36187,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sicherheitscheck: Er trägt ... gelbe Weste 8 Stunden am Tag.'::text,'seine'::text,'ihre'::text,'seine'::text,'Sicherheitscheck: Er trägt seine gelbe Weste 8 Stunden am Tag.'::text),
(325681,36187,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перевірка безпеки: він носить ... жовтий жилет 8 годин на день.'::text,'свій'::text,'свій'::text,'свій'::text,'Перевірка безпеки: він носить свій жовтий жилет 8 годин на день.'::text),
(325680,36187,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Control de seguridad: él lleva ... chaleco amarillo 8 horas al día.'::text,'su'::text,'su'::text,'su'::text,'Control de seguridad: él lleva su chaleco amarillo 8 horas al día.'::text),
(325679,36187,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Contrôle sécurité : il porte ... gilet jaune 8 heures par jour.'::text,'son'::text,'son'::text,'son'::text,'Contrôle sécurité : il porte son gilet jaune 8 heures par jour.'::text),
(325682,36187,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güvenlik kontrolü: ... sarı yeleğini günde 8 saat giyiyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Güvenlik kontrolü: onun sarı yeleğini günde 8 saat giyiyor.'::text),
(325683,36187,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biztonsági ellenőrzés: napi 8 órát hordja a sárga ...'::text,'mellényét'::text,'mellényét'::text,'mellényét'::text,'Biztonsági ellenőrzés: napi 8 órát hordja a sárga mellényét.'::text),
(325695,36189,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast in dieser gelben Weste so ... Style.'::text,'viel'::text,'viele'::text,'eine Menge'::text,'Ehrlich, du hast in dieser gelben Weste so viel Style.'::text),
(325699,36189,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, у тебе в цьому жовтому жилеті так ... стилю.'::text,'багато'::text,'багато'::text,'багато'::text,'Чесно, у тебе в цьому жовтому жилеті так багато стилю.'::text),
(325698,36189,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tienes ... estilo con ese chaleco amarillo.'::text,'mucho'::text,'muchos'::text,'un montón de'::text,'La verdad, tienes mucho estilo con ese chaleco amarillo.'::text),
(325697,36189,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as ... style avec ce gilet jaune.'::text,'beaucoup de'::text,'beaucoup de'::text,'plein de'::text,'Franchement, tu as beaucoup de style avec ce gilet jaune.'::text),
(325700,36189,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası o sarı yelekle o kadar ... tarzın var.'::text,'çok'::text,'çok'::text,'çok'::text,'Açıkçası o sarı yelekle o kadar çok tarzın var.'::text),
(325701,36189,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, olyan ... stílusod van abban a sárga mellényben.'::text,'sok'::text,'sok'::text,'rengeteg'::text,'Őszintén, olyan sok stílusod van abban a sárga mellényben.'::text),
(325704,36190,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... ein Mann in gelber Weste auf dem Dach.'::text,'ist'::text,'sind'::text,'sein'::text,'Da ist ein Mann in gelber Weste auf dem Dach.'::text),
(325708,36190,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На даху ... чоловік у жовтому жилеті.'::text,'є'::text,'є'::text,'бути'::text,'На даху є чоловік у жовтому жилеті.'::text),
(325707,36190,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un hombre con chaleco amarillo en el tejado.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay un hombre con chaleco amarillo en el tejado.'::text),
(325706,36190,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un homme en gilet jaune sur le toit.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a un homme en gilet jaune sur le toit.'::text),
(325709,36190,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çatıda sarı yelekli bir adam ...'::text,'var'::text,'var'::text,'olmak'::text,'Çatıda sarı yelekli bir adam var.'::text),
(325710,36190,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tetőn ... egy férfi sárga mellényben.'::text,'van'::text,'vannak'::text,'lenni'::text,'A tetőn van egy férfi sárga mellényben.'::text),
(313725,34859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie öffnet ... Türen und findet jedes Mal ein neues Zimmer.'::text,'vier'::text,'vierte'::text,'Vieren'::text,'Sie öffnet vier Türen und findet jedes Mal ein neues Zimmer.'::text),
(313729,34859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона відчиняє ... двері і щоразу знаходить нову кімнату.'::text,'чотири'::text,'четверті'::text,'четвірки'::text,'Вона відчиняє чотири двері і щоразу знаходить нову кімнату.'::text),
(313728,34859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abre ... puertas y cada vez encuentra una habitación nueva.'::text,'cuatro'::text,'cuarta'::text,'cuatro'::text,'Abre cuatro puertas y cada vez encuentra una habitación nueva.'::text),
(313727,34859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ouvre ... portes et trouve une nouvelle pièce à chaque fois.'::text,'quatre'::text,'quatrième'::text,'quatre'::text,'Elle ouvre quatre portes et trouve une nouvelle pièce à chaque fois.'::text),
(313730,34859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kapı açıyor ve her seferinde yeni bir oda buluyor.'::text,'Dört'::text,'Dördüncü'::text,'Dörtler'::text,'Dört kapı açıyor ve her seferinde yeni bir oda buluyor.'::text),
(313731,34859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ajtót nyit ki, és minden alkalommal új szobát talál.'::text,'Négy'::text,'Negyedik'::text,'Négyesek'::text,'Négy ajtót nyit ki, és minden alkalommal új szobát talál.'::text),
(313734,34860,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie hat mir erzählt, dass das große Zimmer überhaupt keine ... hat.'::text,'Möbel'::text,'Möbel'::text,'ein Möbelstück'::text,'Mädel, sie hat mir erzählt, dass das große Zimmer überhaupt keine Möbel hat.'::text),
(313738,34860,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що у великій кімнаті взагалі немає ...'::text,'меблів'::text,'меблів'::text,'меблів'::text,'Подруго, вона сказала мені, що у великій кімнаті взагалі немає меблів.'::text),
(313737,34860,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me contó que la habitación grande no tiene ... en absoluto.'::text,'muebles'::text,'muebles'::text,'un mueble'::text,'Tía, me contó que la habitación grande no tiene muebles en absoluto.'::text),
(313736,34860,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit que la grande pièce n''a pas de ... du tout.'::text,'meubles'::text,'meubles'::text,'un meuble'::text,'Meuf, elle m''a dit que la grande pièce n''a pas de meubles du tout.'::text),
(313739,34860,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana büyük odada hiç ... olmadığını söyledi.'::text,'mobilya'::text,'mobilyalar'::text,'bir mobilya'::text,'Kızım, bana büyük odada hiç mobilya olmadığını söyledi.'::text),
(313740,34860,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a nagy szobában egyáltalán nincs ...'::text,'bútor'::text,'bútor'::text,'egy bútor'::text,'Csajszi, azt mondta, hogy a nagy szobában egyáltalán nincs bútor.'::text),
(313743,34861,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lowkey, dieses Haus hat so ... Zimmer, Alter.'::text,'viele'::text,'viel'::text,'eine Menge'::text,'Lowkey, dieses Haus hat so viele Zimmer, Alter.'::text),
(313747,34861,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно кажучи, у цьому будинку так ... кімнат, бро.'::text,'багато'::text,'багато'::text,'багато'::text,'Чесно кажучи, у цьому будинку так багато кімнат, бро.'::text),
(313746,34861,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En plan, esta casa tiene ... habitaciones, tío.'::text,'muchas'::text,'mucha'::text,'un montón de'::text,'En plan, esta casa tiene muchas habitaciones, tío.'::text),
(313745,34861,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, cette maison a ... pièces, frérot.'::text,'beaucoup de'::text,'beaucoup de'::text,'plein de'::text,'Franchement, cette maison a beaucoup de pièces, frérot.'::text),
(313748,34861,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açık konuşayım, bu evde o kadar ... oda var, kanka.'::text,'çok'::text,'çok'::text,'çok'::text,'Açık konuşayım, bu evde o kadar çok oda var, kanka.'::text),
(313749,34861,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lowkey, ennek a háznak olyan ... szobája van, tesó.'::text,'sok'::text,'sok'::text,'rengeteg'::text,'Lowkey, ennek a háznak olyan sok szobája van, tesó.'::text),
(313752,34862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, hinter jeder Tür ... ein geheimes Zimmer, ohne Witz.'::text,'ist'::text,'sind'::text,'sein'::text,'Yo, hinter jeder Tür ist ein geheimes Zimmer, ohne Witz.'::text),
(313756,34862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, за кожними дверима ... таємна кімната, чесно.'::text,'є'::text,'є'::text,'бути'::text,'Йо, за кожними дверима є таємна кімната, чесно.'::text),
(313755,34862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, detrás de cada puerta ... una habitación secreta, en serio.'::text,'hay'::text,'hay'::text,'hay'::text,'Oye, detrás de cada puerta hay una habitación secreta, en serio.'::text),
(313754,34862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, derrière chaque porte, ... une pièce secrète, sans mentir.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Yo, derrière chaque porte, il y a une pièce secrète, sans mentir.'::text),
(313757,34862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, her kapının arkasında gizli bir oda ..., cidden.'::text,'var'::text,'var'::text,'olmak'::text,'Kanka, her kapının arkasında gizli bir oda var, cidden.'::text),
(313758,34862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, minden ajtó mögött ... egy titkos szoba, komolyan.'::text,'van'::text,'vannak'::text,'lenni'::text,'Figyu, minden ajtó mögött van egy titkos szoba, komolyan.'::text),
(313761,34863,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hausregel 1: Gäste ... jede Zimmertür schließen.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Hausregel 1: Gäste müssen jede Zimmertür schließen.'::text),
(313765,34863,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Правило будинку №1: гості ... зачиняти двері кожної кімнати.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Правило будинку №1: гості мають зачиняти двері кожної кімнати.'::text),
(313764,34863,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Norma de la casa n.º 1: los invitados ... cerrar la puerta de cada habitación.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Norma de la casa n.º 1: los invitados tienen que cerrar la puerta de cada habitación.'::text),
(313763,34863,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Règle de la maison n° 1 : les invités ... fermer la porte de chaque pièce.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Règle de la maison n° 1 : les invités doivent fermer la porte de chaque pièce.'::text),
(313766,34863,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev kuralı 1: misafirler her odanın kapısını ...'::text,'kapatmak zorunda'::text,'kapatmalı'::text,'kapatmalı'::text,'Ev kuralı 1: misafirler her odanın kapısını kapatmak zorunda.'::text),
(313767,34863,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'1. házszabály: a vendégeknek minden szoba ajtaját ... becsukniuk.'::text,'kell'::text,'kell'::text,'kellene'::text,'1. házszabály: a vendégeknek minden szoba ajtaját kell becsukniuk.'::text),
(313770,34864,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das große Zimmer ist leer, also ... sie ein paar Möbel hineinstellen.'::text,'sollten'::text,'sollten'::text,'sollten'::text,'Das große Zimmer ist leer, also sollten sie ein paar Möbel hineinstellen.'::text),
(313774,34864,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велика кімната порожня, тож вони ... поставити туди якісь меблі.'::text,'мали б'::text,'мали б'::text,'мали б'::text,'Велика кімната порожня, тож вони мали б поставити туди якісь меблі.'::text),
(313773,34864,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La habitación grande está vacía, así que ellos ... poner algunos muebles.'::text,'deberían'::text,'deberían'::text,'deberían'::text,'La habitación grande está vacía, así que ellos deberían poner algunos muebles.'::text),
(313772,34864,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La grande pièce est vide, alors ils ... y mettre quelques meubles.'::text,'devraient'::text,'devraient'::text,'devraient'::text,'La grande pièce est vide, alors ils devraient y mettre quelques meubles.'::text),
(313775,34864,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük oda boş, bu yüzden içine biraz mobilya ...'::text,'koymalılar'::text,'koymalılar'::text,'koymalılar'::text,'Büyük oda boş, bu yüzden içine biraz mobilya koymalılar.'::text),
(313776,34864,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagy szoba üres, ezért ... tenniük bele néhány bútort.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'A nagy szoba üres, ezért kellene tenniük bele néhány bútort.'::text),
(313797,34867,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Krone und der Umhang ... königlich.'::text,'sind'::text,'ist'::text,'bin'::text,'Die Krone und der Umhang sind königlich.'::text),
