(313810,34868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Королівські музиканти ... для короля.'::text,'грають'::text,'грає'::text,'граючи'::text,'Королівські музиканти грають для короля.'::text),
(313809,34868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los músicos reales ... para el rey.'::text,'tocan'::text,'toca'::text,'tocando'::text,'Los músicos reales tocan para el rey.'::text),
(313808,34868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les musiciens royaux ... pour le roi.'::text,'jouent'::text,'joue'::text,'jouant'::text,'Les musiciens royaux jouent pour le roi.'::text),
(313811,34868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kraliyet müzisyenleri kral için ...'::text,'çalarlar'::text,'çalar'::text,'çalarak'::text,'Kraliyet müzisyenleri kral için çalarlar.'::text),
(313812,34868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A királyi zenészek ... a királynak.'::text,'játszanak'::text,'játszik'::text,'játszó'::text,'A királyi zenészek játszanak a királynak.'::text),
(313815,34869,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Niemand ... die königliche Krone anfassen! Niemals!'::text,'kann'::text,'kann'::text,'kann'::text,'Katastrophe! Niemand kann die königliche Krone anfassen! Niemals!'::text),
(313819,34869,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Ніхто не ... торкатися королівської корони! Ніколи!'::text,'може'::text,'може'::text,'може'::text,'Катастрофа! Ніхто не може торкатися королівської корони! Ніколи!'::text),
(313818,34869,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Nadie ... tocar la corona real! ¡Nunca!'::text,'puede'::text,'puede'::text,'puede'::text,'¡Desastre! ¡Nadie puede tocar la corona real! ¡Nunca!'::text),
(313817,34869,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Personne ne ... toucher la couronne royale ! Jamais !'::text,'peut'::text,'peut'::text,'peut'::text,'Catastrophe ! Personne ne peut toucher la couronne royale ! Jamais !'::text),
(313820,34869,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Kimse kraliyet tacına ...! Asla!'::text,'dokunamaz'::text,'dokunamaz'::text,'dokunamaz'::text,'Felaket! Kimse kraliyet tacına dokunamaz! Asla!'::text),
(313821,34869,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Senki nem ... a királyi koronához! Soha!'::text,'nyúlhat'::text,'nyúlhat'::text,'nyúlhat'::text,'Katasztrófa! Senki nem nyúlhat a királyi koronához! Soha!'::text),
(313842,34872,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, anscheinend ... sich gestern die königliche Menge auf einmal vor ihm.'::text,'verbeugte'::text,'verbeugt'::text,NULL::text,'Okay, anscheinend verbeugte sich gestern die königliche Menge auf einmal vor ihm.'::text),
(313846,34872,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, учора королівський натовп ... йому всі разом.'::text,'вклонився'::text,'вклоняється'::text,NULL::text,'Коротше, кажуть, учора королівський натовп вклонився йому всі разом.'::text),
(313845,34872,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer ayer la multitud real se ... ante él toda a la vez.'::text,'inclinó'::text,'inclina'::text,NULL::text,'Vale, al parecer ayer la multitud real se inclinó ante él toda a la vez.'::text),
(313844,34872,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment hier la foule royale ... devant lui d''un coup.'::text,'s''est inclinée'::text,'s''incline'::text,NULL::text,'Bon, apparemment hier la foule royale s''est inclinée devant lui d''un coup.'::text),
(313847,34872,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre dün kraliyet kalabalığı ona hep birlikte ...'::text,'eğildi'::text,'eğilir'::text,NULL::text,'Tamam, duyduğuma göre dün kraliyet kalabalığı ona hep birlikte eğildi.'::text),
(313848,34872,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag tegnap a királyi tömeg egyszerre ... meg előtte.'::text,'hajolt'::text,'hajol'::text,NULL::text,'Szóval állítólag tegnap a királyi tömeg egyszerre hajolt meg előtte.'::text),
(313851,34873,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dein Umhang sieht ... aus als jeder königliche Umhang, den ich kenne.'::text,'leuchtender'::text,'leuchtender'::text,'am leuchtendsten'::text,'Ehrlich, dein Umhang sieht leuchtender aus als jeder königliche Umhang, den ich kenne.'::text),
(313855,34873,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твій плащ виглядає ... за будь-який королівський плащ, який я знаю.'::text,'яскравішим'::text,'яскравішим'::text,'найяскравішим'::text,'Чесно, твій плащ виглядає яскравішим за будь-який королівський плащ, який я знаю.'::text),
(313854,34873,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tu capa se ve ... que cualquier capa real que conozco.'::text,'más brillante'::text,'más brillante'::text,'la más brillante'::text,'La verdad, tu capa se ve más brillante que cualquier capa real que conozco.'::text),
(313853,34873,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ta cape a l''air ... que toutes les capes royales que je connais.'::text,'plus éclatante'::text,'plus éclatante'::text,'la plus éclatante'::text,'Franchement, ta cape a l''air plus éclatante que toutes les capes royales que je connais.'::text),
(313856,34873,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası pelerinin bildiğim tüm kraliyet pelerinlerinden ... görünüyor.'::text,'daha parlak'::text,'daha parlak'::text,'en parlak'::text,'Açıkçası pelerinin bildiğim tüm kraliyet pelerinlerinden daha parlak görünüyor.'::text),
(313857,34873,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a köpenyed ... bármelyik királyi köpenynél, amit ismerek.'::text,'ragyogóbb'::text,'ragyogóbb'::text,'legragyogóbb'::text,'Őszintén, a köpenyed ragyogóbb bármelyik királyi köpenynél, amit ismerek.'::text),
(313860,34874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Du hältst dieses königliche Zepter so ...'::text,'stolz.'::text,'stolz.'::text,'stolz.'::text,'Respekt: Du hältst dieses königliche Zepter so stolz.'::text),
(313864,34874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: ти тримаєш цей королівський скіпетр так ...'::text,'гордо.'::text,'гордий.'::text,'гордо.'::text,'Респект: ти тримаєш цей королівський скіпетр так гордо.'::text),
(313863,34874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: sostienes ese cetro real tan ...'::text,'orgullosamente.'::text,'orgulloso.'::text,'orgullosamente.'::text,'Respeto: sostienes ese cetro real tan orgullosamente.'::text),
(313862,34874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : tu tiens ce sceptre royal si ...'::text,'fièrement.'::text,'fier.'::text,'fièrement.'::text,'Respect : tu tiens ce sceptre royal si fièrement.'::text),
(313865,34874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar: o kraliyet asasını öyle ... tutuyorsun.'::text,'gururla'::text,'gururlu'::text,'gururla'::text,'Saygılar: o kraliyet asasını öyle gururla tutuyorsun.'::text),
(313866,34874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: olyan ... tartod azt a királyi jogart.'::text,'büszkén'::text,'büszke'::text,'büszkén'::text,'Respekt: olyan büszkén tartod azt a királyi jogart.'::text),
(294582,32732,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jedes Rennen, das sie anfängt.'::text,'beendet'::text,'beenden'::text,'beendend'::text,'Sie beendet jedes Rennen, das sie anfängt.'::text),
(294586,32732,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... кожен забіг, який починає.'::text,'завершує'::text,'завершувати'::text,'завершуючи'::text,'Вона завершує кожен забіг, який починає.'::text),
(294585,32732,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... cada carrera que empieza.'::text,'termina'::text,'terminar'::text,'terminando'::text,'Ella termina cada carrera que empieza.'::text),
(294584,32732,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... chaque course qu''elle commence.'::text,'termine'::text,'terminer'::text,'terminant'::text,'Elle termine chaque course qu''elle commence.'::text),
(294587,32732,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başladığı her yarışı ...'::text,'bitirir'::text,'bitirmek'::text,'bitirerek'::text,'Başladığı her yarışı bitirir.'::text),
(294588,32732,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... minden versenyt, amit elkezd.'::text,'Befejez'::text,'Befejezni'::text,'Befejező'::text,'Befejez minden versenyt, amit elkezd.'::text),
(294591,32733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das Rennen vor der anderen Läuferin beenden.'::text,'kann'::text,'kann'::text,'ist'::text,'Sie kann das Rennen vor der anderen Läuferin beenden.'::text),
(294595,32733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... завершити забіг раніше за іншу бігунку.'::text,'може'::text,'може'::text,'є'::text,'Вона може завершити забіг раніше за іншу бігунку.'::text),
(294594,32733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... terminar la carrera antes que la otra corredora.'::text,'puede'::text,'puede'::text,'está'::text,'Ella puede terminar la carrera antes que la otra corredora.'::text),
(294593,32733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... finir la course avant l''autre coureuse.'::text,'peut'::text,'peut'::text,'est'::text,'Elle peut finir la course avant l''autre coureuse.'::text),
(294596,32733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarışı diğer koşucudan önce ...'::text,'bitirebilir'::text,'bitirebilir'::text,NULL::text,'Yarışı diğer koşucudan önce bitirebilir.'::text),
(294597,32733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a versenyt a másik futó előtt.'::text,'Befejezheti'::text,'Befejezheti'::text,'Van'::text,'Befejezheti a versenyt a másik futó előtt.'::text),
(294609,32735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... sie das Rennen als Erste und hielt nicht mal an.'::text,'beendete'::text,'beendet'::text,'beenden'::text,'Mädel, anscheinend beendete sie das Rennen als Erste und hielt nicht mal an.'::text),
(294613,32735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... забіг першою і навіть не зупинилася.'::text,'завершила'::text,'завершує'::text,'завершувати'::text,'Подруго, кажуть, вона завершила забіг першою і навіть не зупинилася.'::text),
(294612,32735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ella ... la carrera la primera y ni siquiera paró.'::text,'terminó'::text,'termina'::text,'terminar'::text,'Tía, al parecer ella terminó la carrera la primera y ni siquiera paró.'::text),
(294611,32735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... la course en premier et elle s''est même pas arrêtée.'::text,'a fini'::text,'finit'::text,'finir'::text,'Meuf, apparemment elle a fini la course en premier et elle s''est même pas arrêtée.'::text),
(294614,32735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre yarışı birinci ... ve hiç durmadı bile.'::text,'bitirdi'::text,'bitirir'::text,'bitirmek'::text,'Kızım, duyduğuma göre yarışı birinci bitirdi ve hiç durmadı bile.'::text),
(294615,32735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag elsőként ... a versenyt, és meg sem állt.'::text,'fejezte be'::text,'fejezi be'::text,'befejezni'::text,'Csajszi, állítólag elsőként fejezte be a versenyt, és meg sem állt.'::text),
(294618,32736,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziemlich beeindruckend: Normalerweise gehst du, aber heute ... du ein ganzes Rennen.'::text,'beendetest'::text,'beendest'::text,NULL::text,'Ziemlich beeindruckend: Normalerweise gehst du, aber heute beendetest du ein ganzes Rennen.'::text),
(294622,32736,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досить вражає: зазвичай ти ходиш пішки, але сьогодні ти ... цілий забіг.'::text,'завершила'::text,'завершуєш'::text,NULL::text,'Досить вражає: зазвичай ти ходиш пішки, але сьогодні ти завершила цілий забіг.'::text),
(294621,32736,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante impresionante: normalmente caminas, pero hoy tú ... una carrera entera.'::text,'has terminado'::text,'terminas'::text,NULL::text,'Bastante impresionante: normalmente caminas, pero hoy tú has terminado una carrera entera.'::text),
(294620,32736,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plutôt impressionnant : d''habitude tu marches, mais aujourd''hui tu ... une course entière.'::text,'as fini'::text,'finis'::text,NULL::text,'Plutôt impressionnant : d''habitude tu marches, mais aujourd''hui tu as fini une course entière.'::text),
(294623,32736,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Epey etkileyici: genelde yürürsün ama bugün koca bir yarışı ...'::text,'bitirdin'::text,'bitirirsin'::text,NULL::text,'Epey etkileyici: genelde yürürsün ama bugün koca bir yarışı bitirdin.'::text),
(294624,32736,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég lenyűgöző: általában sétálsz, de ma ... egy egész versenyt.'::text,'befejeztél'::text,'befejezel'::text,NULL::text,'Elég lenyűgöző: általában sétálsz, de ma befejeztél egy egész versenyt.'::text),
(294627,32737,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, deine Regel ist Kult: Du ... jedes Rennen beenden, das du anfängst.'::text,'musst'::text,'musst'::text,'solltest'::text,'Ehrlich, deine Regel ist Kult: Du musst jedes Rennen beenden, das du anfängst.'::text),
(294631,32737,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твоє правило — легенда: ти ... завершувати кожен забіг, який починаєш.'::text,'мусиш'::text,'маєш'::text,'мала б'::text,'Чесно, твоє правило — легенда: ти мусиш завершувати кожен забіг, який починаєш.'::text),
(294630,32737,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tu regla es icónica: tú ... terminar cada carrera que empiezas.'::text,'debes'::text,'tienes que'::text,'deberías'::text,'La verdad, tu regla es icónica: tú debes terminar cada carrera que empiezas.'::text),
(294629,32737,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ta règle est iconique : tu ... finir chaque course que tu commences.'::text,'dois'::text,'dois'::text,'devrais'::text,'Franchement, ta règle est iconique : tu dois finir chaque course que tu commences.'::text),
(294632,32737,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası kuralın efsane: başladığın her yarışı ...'::text,'bitirmelisin'::text,'bitirmek zorundasın'::text,'bitirmelisin'::text,'Açıkçası kuralın efsane: başladığın her yarışı bitirmelisin.'::text),
(294633,32737,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ikonikus a szabályod: minden versenyt, amit elkezdesz, be ... fejezned.'::text,'kell'::text,'kell'::text,'kellene'::text,'Őszintén, ikonikus a szabályod: minden versenyt, amit elkezdesz, be kell fejezned.'::text),
(294636,32738,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine total langsame Läuferin, klar. Sie ... nächstes Mal schneller ins Ziel kommen.'::text,'sollte'::text,'soll'::text,'sollte'::text,'Eine total langsame Läuferin, klar. Sie sollte nächstes Mal schneller ins Ziel kommen.'::text),
(294640,32738,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже повільна бігунка, звісно. Вона ... наступного разу фінішувати швидше.'::text,'мала б'::text,'буде'::text,'мала б'::text,'Дуже повільна бігунка, звісно. Вона мала б наступного разу фінішувати швидше.'::text),
(294639,32738,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una corredora lentísima, obviamente. Ella ... terminar más rápido la próxima vez.'::text,'debería'::text,'deberá'::text,'debería'::text,'Una corredora lentísima, obviamente. Ella debería terminar más rápido la próxima vez.'::text),
(294638,32738,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une coureuse très lente, évidemment. Elle ... finir plus vite la prochaine fois.'::text,'devrait'::text,'devra'::text,'devrait'::text,'Une coureuse très lente, évidemment. Elle devrait finir plus vite la prochaine fois.'::text),
(294641,32738,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok yavaş bir koşucu tabii. Bir dahaki sefere daha hızlı ...'::text,'bitirmeli'::text,'bitirecek'::text,'bitirmeli'::text,'Çok yavaş bir koşucu tabii. Bir dahaki sefere daha hızlı bitirmeli.'::text),
(294642,32738,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon lassú futó, nyilván. Legközelebb gyorsabban ... célba érnie.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Nagyon lassú futó, nyilván. Legközelebb gyorsabban kellene célba érnie.'::text),
(319062,35452,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wüstenhimmel ... jede Menge Sterne.'::text,'hat'::text,'haben'::text,'hat'::text,'Der Wüstenhimmel hat jede Menge Sterne.'::text),
(319066,35452,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пустельне небо ... багато зірок.'::text,'має'::text,'мати'::text,'має'::text,'Пустельне небо має багато зірок.'::text),
(319065,35452,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cielo del desierto ... muchísimas estrellas.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'El cielo del desierto tiene muchísimas estrellas.'::text),
(319064,35452,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le ciel du désert ... plein d''étoiles.'::text,'a'::text,'ont'::text,'a'::text,'Le ciel du désert a plein d''étoiles.'::text),
(319067,35452,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çöl gökyüzünün bir sürü yıldızı ...'::text,'var'::text,'var'::text,'var'::text,'Çöl gökyüzünün bir sürü yıldızı var.'::text),
(319068,35452,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sivatagi égnek rengeteg csillaga ...'::text,'van'::text,'van'::text,'van'::text,'A sivatagi égnek rengeteg csillaga van.'::text),
(319071,35453,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er kann Hunderte von ... am Himmel sehen.'::text,'Sternen'::text,'Stern'::text,'Sternen'::text,'Er kann Hunderte von Sternen am Himmel sehen.'::text),
(319075,35453,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він бачить на небі сотні ...'::text,'зірок'::text,'зірка'::text,'зірок'::text,'Він бачить на небі сотні зірок.'::text),
(319074,35453,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Puede ver cientos de ... en el cielo.'::text,'estrellas'::text,'estrella'::text,'estrellas'::text,'Puede ver cientos de estrellas en el cielo.'::text),
(319073,35453,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il peut voir des centaines d''... dans le ciel.'::text,'étoiles'::text,'étoile'::text,'étoiles'::text,'Il peut voir des centaines d''étoiles dans le ciel.'::text),
(319076,35453,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökyüzünde yüzlerce ... görebiliyor.'::text,'yıldız'::text,'yıldız'::text,'yıldız'::text,'Gökyüzünde yüzlerce yıldız görebiliyor.'::text),
(319077,35453,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Több száz ... lát az égen.'::text,'csillagot'::text,'csillagot'::text,'csillagot'::text,'Több száz csillagot lát az égen.'::text),
(319080,35454,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du suchst dir ... besten Platz zum Sternegucken aus.'::text,'den'::text,'einen'::text,'einen'::text,'Ehrlich, du suchst dir den besten Platz zum Sternegucken aus.'::text),
(319084,35454,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти обираєш ... найкраще місце, щоб дивитися на зірки.'::text,''::text,NULL::text,NULL::text,'Чесно, ти обираєш найкраще місце, щоб дивитися на зірки.'::text),
(319083,35454,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, eliges ... mejor sitio para ver las estrellas.'::text,'el'::text,'un'::text,'un'::text,'La verdad, eliges el mejor sitio para ver las estrellas.'::text),
(319082,35454,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu choisis ... meilleur coin pour regarder les étoiles.'::text,'le'::text,'un'::text,'un'::text,'Franchement, tu choisis le meilleur coin pour regarder les étoiles.'::text),
(319085,35454,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası yıldızları izlemek için ... en iyi yeri seçiyorsun.'::text,''::text,'bir'::text,'bir'::text,'Açıkçası yıldızları izlemek için en iyi yeri seçiyorsun.'::text),
(319086,35454,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... legjobb helyet választod a csillagnézéshez.'::text,'a'::text,'egy'::text,'egy'::text,'Őszintén, a legjobb helyet választod a csillagnézéshez.'::text),
(319098,35456,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hebt ... Tasse unter den Sternen.'::text,'seine'::text,'ihre'::text,'seine'::text,'Er hebt seine Tasse unter den Sternen.'::text),
(319102,35456,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він піднімає ... чашку під зорями.'::text,'свою'::text,'свою'::text,'свою'::text,'Він піднімає свою чашку під зорями.'::text),
(319101,35456,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Levanta ... taza bajo las estrellas.'::text,'su'::text,'su'::text,'su'::text,'Levanta su taza bajo las estrellas.'::text),
(319100,35456,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il lève ... tasse sous les étoiles.'::text,'sa'::text,'sa'::text,'sa'::text,'Il lève sa tasse sous les étoiles.'::text),
(319103,35456,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıldızların altında ... bardağını kaldırıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Yıldızların altında onun bardağını kaldırıyor.'::text),
(319104,35456,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felemeli a ... a csillagok alatt.'::text,'bögréjét'::text,'bögréjét'::text,'bögréjét'::text,'Felemeli a bögréjét a csillagok alatt.'::text),
(319107,35457,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Sterne kommen ... Nacht raus, und mein Handy ist leer! Katastrophe!'::text,'bei'::text,'in'::text,'an'::text,'Die Sterne kommen bei Nacht raus, und mein Handy ist leer! Katastrophe!'::text),
(319111,35457,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зорі з''являються ..., а мій телефон сів! Катастрофа!'::text,'вночі'::text,'у ніч'::text,'на ніч'::text,'Зорі з''являються вночі, а мій телефон сів! Катастрофа!'::text),
(319110,35457,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Las estrellas salen ... noche y mi móvil está muerto! ¡Desastre!'::text,'de'::text,'en'::text,'sobre'::text,'¡Las estrellas salen de noche y mi móvil está muerto! ¡Desastre!'::text),
(319109,35457,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les étoiles sortent ... la nuit, et mon téléphone est mort ! Catastrophe !'::text,''::text,'dans'::text,'sur'::text,'Les étoiles sortent la nuit, et mon téléphone est mort ! Catastrophe !'::text),
(319112,35457,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıldızlar gece ... çıkıyor ve telefonumun şarjı bitti! Felaket!'::text,''::text,NULL::text,NULL::text,'Yıldızlar gece çıkıyor ve telefonumun şarjı bitti! Felaket!'::text),
(319113,35457,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csillagok ... jönnek elő, és lemerült a telefonom! Katasztrófa!'::text,'éjszaka'::text,'éjszakában'::text,'éjszakán'::text,'A csillagok éjszaka jönnek elő, és lemerült a telefonom! Katasztrófa!'::text),
(319116,35458,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Völlig verrückt! Ich kann über dem Feuer ... Sterne sehen!'::text,'hundert'::text,'hundertste'::text,'Hunderte'::text,'Völlig verrückt! Ich kann über dem Feuer hundert Sterne sehen!'::text),
(319120,35458,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто божевілля! Я бачу над вогнем ... зірок!'::text,'сто'::text,'соту'::text,'сотні'::text,'Просто божевілля! Я бачу над вогнем сто зірок!'::text),
(319119,35458,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Una locura total! ¡Puedo ver ... estrellas sobre el fuego!'::text,'cien'::text,'centésima'::text,'cien'::text,'¡Una locura total! ¡Puedo ver cien estrellas sobre el fuego!'::text),
(319118,35458,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Complètement fou ! Je peux voir ... étoiles au-dessus du feu !'::text,'cent'::text,'centième'::text,'cent'::text,'Complètement fou ! Je peux voir cent étoiles au-dessus du feu !'::text),
(319121,35458,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resmen çılgınlık! Ateşin üstünde ... yıldız görebiliyorum!'::text,'yüz'::text,'yüzüncü'::text,'yüzler'::text,'Resmen çılgınlık! Ateşin üstünde yüz yıldız görebiliyorum!'::text),
(319122,35458,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totál őrület! ... csillagot látok a tűz fölött!'::text,'Száz'::text,'Századik'::text,'Százasok'::text,'Totál őrület! Száz csillagot látok a tűz fölött!'::text),
(312483,34721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise zahlt sie Miete für ein Fahrrad, aber heute ... sie einen Motorroller.'::text,'fährt'::text,'fährt'::text,NULL::text,'Normalerweise zahlt sie Miete für ein Fahrrad, aber heute fährt sie einen Motorroller.'::text),
(312487,34721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона платить оренду за велосипед, але сьогодні вона ... на скутері.'::text,'їде'::text,'їде'::text,NULL::text,'Зазвичай вона платить оренду за велосипед, але сьогодні вона їде на скутері.'::text),
(312486,34721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente paga alquiler por una bici, pero hoy ella ... en escúter.'::text,'está montando'::text,'monta'::text,NULL::text,'Normalmente paga alquiler por una bici, pero hoy ella está montando en escúter.'::text),
(312485,34721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, elle paie une location pour un vélo, mais aujourd''hui elle ... un scooter.'::text,'est en train de conduire'::text,'conduit'::text,NULL::text,'D''habitude, elle paie une location pour un vélo, mais aujourd''hui elle est en train de conduire un scooter.'::text),
(312488,34721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde bisiklet için kira öder ama bugün scooter ...'::text,'sürüyor'::text,'sürer'::text,NULL::text,'Genelde bisiklet için kira öder ama bugün scooter sürüyor.'::text),
(312489,34721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában bicikliért fizet bérleti díjat, de ma robogóval ...'::text,'megy'::text,'megy'::text,NULL::text,'Általában bicikliért fizet bérleti díjat, de ma robogóval megy.'::text),
(312492,34722,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen ... die Miete für einen Motorroller höher sein, glaube ich.'::text,'wird'::text,'war'::text,'wird'::text,'Morgen wird die Miete für einen Motorroller höher sein, glaube ich.'::text),
(312496,34722,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра оренда скутера ... вищою, я думаю.'::text,'буде'::text,'була'::text,'буде'::text,'Завтра оренда скутера буде вищою, я думаю.'::text),
(312495,34722,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana el alquiler de un escúter ... más alto, creo.'::text,'será'::text,'fue'::text,'será'::text,'Mañana el alquiler de un escúter será más alto, creo.'::text),
(312494,34722,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain, la location d''un scooter ... plus chère, je pense.'::text,'sera'::text,'était'::text,'sera'::text,'Demain, la location d''un scooter sera plus chère, je pense.'::text),
(312497,34722,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence yarın scooter kirası daha yüksek ...'::text,'olacak'::text,'idi'::text,'olacak'::text,'Bence yarın scooter kirası daha yüksek olacak.'::text),
(312498,34722,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap a robogó bérleti díja magasabb ..., szerintem.'::text,'lesz'::text,'volt'::text,'lesz'::text,'Holnap a robogó bérleti díja magasabb lesz, szerintem.'::text),
(312501,34723,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budgetplan: Sie ... täglich 5 Euro Miete für den Motorroller zahlen.'::text,'wird'::text,'wird'::text,'werden'::text,'Budgetplan: Sie wird täglich 5 Euro Miete für den Motorroller zahlen.'::text),
(312505,34723,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджетний план: вона ... платити 5 євро за оренду скутера на день.'::text,'збирається'::text,'збирається'::text,'збираються'::text,'Бюджетний план: вона збирається платити 5 євро за оренду скутера на день.'::text),
(312504,34723,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan de presupuesto: ella ... pagar 5 euros de alquiler de escúter al día.'::text,'va a'::text,'va a'::text,'van a'::text,'Plan de presupuesto: ella va a pagar 5 euros de alquiler de escúter al día.'::text),
(312503,34723,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan budget : elle ... payer 5 euros de location de scooter par jour.'::text,'va'::text,'va'::text,'vont'::text,'Plan budget : elle va payer 5 euros de location de scooter par jour.'::text),
(312506,34723,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe planı: günde 5 euro scooter kirası ...'::text,'ödeyecek'::text,'ödeyecek'::text,'ödeyecekler'::text,'Bütçe planı: günde 5 euro scooter kirası ödeyecek.'::text),
(312507,34723,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségterv: napi 5 euró robogóbérleti díjat ... fizetni.'::text,'fog'::text,'fog'::text,'fognak'::text,'Költségterv: napi 5 euró robogóbérleti díjat fog fizetni.'::text),
(312510,34724,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Handy hat die App, also ... sie die Miete mit dem Handy zahlen.'::text,'wird'::text,'wird'::text,NULL::text,'Ihr Handy hat die App, also wird sie die Miete mit dem Handy zahlen.'::text),
(312514,34724,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У її телефоні є застосунок, тож вона ... платити оренду телефоном.'::text,'збирається'::text,'буде'::text,NULL::text,'У її телефоні є застосунок, тож вона збирається платити оренду телефоном.'::text),
(312513,34724,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su móvil tiene la app, así que ella ... pagar el alquiler con el móvil.'::text,'va a'::text,NULL::text,NULL::text,'Su móvil tiene la app, así que ella va a pagar el alquiler con el móvil.'::text),
(312512,34724,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son téléphone a l''appli, donc elle ... payer la location avec son téléphone.'::text,'va'::text,NULL::text,NULL::text,'Son téléphone a l''appli, donc elle va payer la location avec son téléphone.'::text),
(312515,34724,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefonunda uygulama var, bu yüzden kirayı telefonuyla ...'::text,'ödeyecek'::text,'ödeyecek'::text,NULL::text,'Telefonunda uygulama var, bu yüzden kirayı telefonuyla ödeyecek.'::text),
(312516,34724,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A telefonján megvan az app, úgyhogy a telefonjával ... kifizetni a bérleti díjat.'::text,'fogja'::text,'fogja'::text,NULL::text,'A telefonján megvan az app, úgyhogy a telefonjával fogja kifizetni a bérleti díjat.'::text),
(312519,34725,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Die Motorroller-Miete frisst jede Woche mein ganzes ...!'::text,'Geld'::text,'Geld'::text,'ein Geld'::text,'Katastrophe! Die Motorroller-Miete frisst jede Woche mein ganzes Geld!'::text),
(312523,34725,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Оренда скутера щотижня з''їдає всі мої ...!'::text,'гроші'::text,'гроші'::text,'гроші'::text,'Катастрофа! Оренда скутера щотижня з''їдає всі мої гроші!'::text),
(312522,34725,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡El alquiler del escúter se come todo mi ... cada semana!'::text,'dinero'::text,'dinero'::text,'un dinero'::text,'¡Desastre! ¡El alquiler del escúter se come todo mi dinero cada semana!'::text),
(312521,34725,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! La location du scooter mange tout mon ... chaque semaine !'::text,'argent'::text,'argent'::text,'un argent'::text,'Catastrophe ! La location du scooter mange tout mon argent chaque semaine !'::text),
(312524,34725,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Scooter kirası her hafta bütün ... yiyor!'::text,'paramı'::text,'paralarımı'::text,'bir para'::text,'Felaket! Scooter kirası her hafta bütün paramı yiyor!'::text),
(312525,34725,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A robogó bérleti díja minden héten felzabálja az összes ...!'::text,'pénzemet'::text,'pénzemet'::text,'egy pénzt'::text,'Katasztrófa! A robogó bérleti díja minden héten felzabálja az összes pénzemet!'::text),
(312528,34726,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Ich habe nicht ... Geld für die Motorroller-Miete!'::text,'viel'::text,'viele'::text,'eine Menge'::text,'Albtraum! Ich habe nicht viel Geld für die Motorroller-Miete!'::text),
(312532,34726,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! У мене немає ... грошей на оренду скутера!'::text,'багато'::text,'багато'::text,'багато'::text,'Жах! У мене немає багато грошей на оренду скутера!'::text),
(312531,34726,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡No tengo ... dinero para el alquiler del escúter!'::text,'mucho'::text,'muchos'::text,'un montón de'::text,'¡Pesadilla! ¡No tengo mucho dinero para el alquiler del escúter!'::text),
(312530,34726,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Je n''ai pas ... argent pour la location du scooter !'::text,'beaucoup d'''::text,'beaucoup d'''::text,'plein d'''::text,'Cauchemar ! Je n''ai pas beaucoup d'' argent pour la location du scooter !'::text),
(312533,34726,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Scooter kirası için ... param yok!'::text,'çok'::text,'çok'::text,'çok'::text,'Kâbus! Scooter kirası için çok param yok!'::text),
(312534,34726,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Nincs ... pénzem a robogó bérleti díjára!'::text,'sok'::text,'sok'::text,'rengeteg'::text,'Rémálom! Nincs sok pénzem a robogó bérleti díjára!'::text),
(312546,34728,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat gesagt, du ... zuerst die Miete in der App checken.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Bestie, sie hat gesagt, du solltest zuerst die Miete in der App checken.'::text),
(312550,34728,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала, що ти ... спочатку перевірити оренду в застосунку.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Подруго, вона сказала, що ти мала б спочатку перевірити оренду в застосунку.'::text),
(312549,34728,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, dijo que tú ... mirar primero el alquiler en la app.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'Amiga, dijo que tú deberías mirar primero el alquiler en la app.'::text),
(312548,34728,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle a dit que tu ... d''abord vérifier la location dans l''appli.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Ma belle, elle a dit que tu devrais d''abord vérifier la location dans l''appli.'::text),
(312551,34728,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, önce uygulamadan kirayı ... dedi.'::text,'kontrol etmelisin'::text,'kontrol etmelisin'::text,'kontrol etmelisin'::text,'Kanka, önce uygulamadan kirayı kontrol etmelisin dedi.'::text),
(312552,34728,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, azt mondta, hogy előbb meg ... nézned a bérleti díjat az appban.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Bestie, azt mondta, hogy előbb meg kellene nézned a bérleti díjat az appban.'::text),
(326334,36260,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pfannen werden dreckig, also ... er sie spülen.'::text,'kann'::text,'kann'::text,'kann'::text,'Pfannen werden dreckig, also kann er sie spülen.'::text),
(326338,36260,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сковорідки брудняться, тож він ... їх помити.'::text,'може'::text,'може'::text,'може'::text,'Сковорідки брудняться, тож він може їх помити.'::text),
(326337,36260,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las sartenes se ensucian, así que él ... lavarlas.'::text,'puede'::text,'puede'::text,'puede'::text,'Las sartenes se ensucian, así que él puede lavarlas.'::text),
(326336,36260,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les poêles se salissent, alors il ... les laver.'::text,'peut'::text,'peut'::text,'peut'::text,'Les poêles se salissent, alors il peut les laver.'::text),
(326339,36260,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavalar kirlenir, bu yüzden onları ...'::text,'yıkayabilir'::text,'yıkayabilir'::text,'yıkayabilir'::text,'Tavalar kirlenir, bu yüzden onları yıkayabilir.'::text),
(326340,36260,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A serpenyők koszosak lesznek, úgyhogy ... őket.'::text,'el tudja mosni'::text,'el tudja mosni'::text,'el tudja mosni'::text,'A serpenyők koszosak lesznek, úgyhogy el tudja mosni őket.'::text),
(326343,36261,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... spülst du diese schwarzen Pfannen so gut? Echt beeindruckend.'::text,'Wie'::text,'Wer'::text,'Wo'::text,'Wie spülst du diese schwarzen Pfannen so gut? Echt beeindruckend.'::text),
