(326352,36262,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht gelogen, du ... gestern jede rußige Pfanne in der Küche.'::text,'spültest'::text,'spült'::text,'spültest'::text,'Nicht gelogen, du spültest gestern jede rußige Pfanne in der Küche.'::text),
