(326355,36262,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ayer tú ... cada sartén tiznada de la cocina.'::text,'lavaste'::text,'lava'::text,'lavaste'::text,'No voy a mentir, ayer tú lavaste cada sartén tiznada de la cocina.'::text),
(326354,36262,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, hier tu ... chaque poêle noircie de la cuisine.'::text,'as lavé'::text,'lave'::text,'as lavé'::text,'Je vais pas mentir, hier tu as lavé chaque poêle noircie de la cuisine.'::text),
(326357,36262,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, dün mutfaktaki her isli tavayı ...'::text,'yıkadın'::text,'yıkar'::text,'yıkadın'::text,'Yalan yok, dün mutfaktaki her isli tavayı yıkadın.'::text),
(326358,36262,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, tegnap ... a konyhában minden kormos serpenyőt.'::text,'elmostad'::text,'elmossa'::text,'elmostad'::text,'Nem hazudok, tegnap elmostad a konyhában minden kormos serpenyőt.'::text),
