(326365,36263,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай ти миєш тарілки, але вчора ти ... пригорілу каструлю. Респект.'::text,'помив'::text,'миєш'::text,NULL::text,'Зазвичай ти миєш тарілки, але вчора ти помив пригорілу каструлю. Респект.'::text),
(326364,36263,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente lavas platos, pero ayer tú ... una olla quemada. Respeto.'::text,'lavaste'::text,'lavas'::text,NULL::text,'Normalmente lavas platos, pero ayer tú lavaste una olla quemada. Respeto.'::text),
(326363,36263,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, tu laves des assiettes, mais hier tu ... une casserole brûlée. Respect.'::text,'as lavé'::text,'laves'::text,NULL::text,'D''habitude, tu laves des assiettes, mais hier tu as lavé une casserole brûlée. Respect.'::text),
(326366,36263,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde tabak yıkarsın ama dün yanık bir tencere ... Saygılar.'::text,'yıkadın'::text,'yıkarsın'::text,NULL::text,'Genelde tabak yıkarsın ama dün yanık bir tencere yıkadın Saygılar.'::text),
(326367,36263,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában tányérokat mosol, de tegnap egy odaégett lábast ... Respekt.'::text,'mostál el'::text,'mosol el'::text,NULL::text,'Általában tányérokat mosol, de tegnap egy odaégett lábast mostál el Respekt.'::text),
(326370,36264,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein schneller Job, klar: Er ... seit einer Stunde dieselbe schwarze Pfanne.'::text,'spült'::text,'spült'::text,'spült'::text,'Ein schneller Job, klar: Er spült seit einer Stunde dieselbe schwarze Pfanne.'::text),
(326374,36264,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Швидка робота, звісно: він ... ту саму чорну сковорідку вже годину.'::text,'миє'::text,'миє'::text,'миє'::text,'Швидка робота, звісно: він миє ту саму чорну сковорідку вже годину.'::text),
(326373,36264,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un trabajo rápido, obviamente: él ... la misma sartén negra desde hace una hora.'::text,'está lavando'::text,'lava'::text,'está lavando'::text,'Un trabajo rápido, obviamente: él está lavando la misma sartén negra desde hace una hora.'::text),
(326372,36264,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un boulot rapide, évidemment : il ... la même poêle noire depuis une heure.'::text,'est en train de laver'::text,'lave'::text,'est en train de laver'::text,'Un boulot rapide, évidemment : il est en train de laver la même poêle noire depuis une heure.'::text),
