(325202,36134,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu tapes tellement vite ... tu connais chaque touche. Impressionnant, franchement.'::text,'parce que'::text,'mais'::text,'donc'::text,'Tu tapes tellement vite parce que tu connais chaque touche. Impressionnant, franchement.'::text),
(325205,36134,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar hızlı yazıyorsun ... her tuşu biliyorsun. Cidden etkileyici.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'O kadar hızlı yazıyorsun çünkü her tuşu biliyorsun. Cidden etkileyici.'::text),
(325206,36134,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan gyorsan gépelsz, ... minden billentyűt ismersz. Lenyűgöző, őszintén.'::text,'mert'::text,'de'::text,'ezért'::text,'Olyan gyorsan gépelsz, mert minden billentyűt ismersz. Lenyűgöző, őszintén.'::text),
(315039,35005,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tanzt ihr so gut im Seniorenkurs? Respekt.'::text,'Wie'::text,'Wer'::text,'Wo'::text,'Wie tanzt ihr so gut im Seniorenkurs? Respekt.'::text),
(315043,35005,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ви так добре танцюєте на заняттях для літніх? Респект.'::text,'Як'::text,'Хто'::text,'Де'::text,'Як ви так добре танцюєте на заняттях для літніх? Респект.'::text),
(315042,35005,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... bailáis tan bien en la clase de mayores? Respeto.'::text,'Cómo'::text,'Quién'::text,'Dónde'::text,'¿Cómo bailáis tan bien en la clase de mayores? Respeto.'::text),
(315041,35005,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... vous dansez aussi bien au cours pour seniors ? Respect.'::text,'Comment'::text,'Qui'::text,'Où'::text,'Comment vous dansez aussi bien au cours pour seniors ? Respect.'::text),
(315044,35005,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlılar sınıfında ... bu kadar iyi dans ediyorsunuz? Saygılar.'::text,'nasıl'::text,'kim'::text,'nerede'::text,'Yaşlılar sınıfında nasıl bu kadar iyi dans ediyorsunuz? Saygılar.'::text),
(315045,35005,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... táncoltok ilyen jól a szenior órán? Respekt.'::text,'Hogyan'::text,'Ki'::text,'Hol'::text,'Hogyan táncoltok ilyen jól a szenior órán? Respekt.'::text),
(315057,35007,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Seniorengruppe tanzt jeden Sonntag, und letzten Sonntag ... sie im Park.'::text,'tanzten'::text,'tanzen'::text,NULL::text,'Die Seniorengruppe tanzt jeden Sonntag, und letzten Sonntag tanzten sie im Park.'::text),
(315061,35007,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Група літніх людей танцює щонеділі, а минулої неділі вони ... в парку.'::text,'танцювали'::text,'танцюють'::text,NULL::text,'Група літніх людей танцює щонеділі, а минулої неділі вони танцювали в парку.'::text),
(315060,35007,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El grupo de mayores baila todos los domingos, y el domingo pasado ellos ... en el parque.'::text,'bailaron'::text,'bailan'::text,NULL::text,'El grupo de mayores baila todos los domingos, y el domingo pasado ellos bailaron en el parque.'::text),
(315059,35007,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe de seniors danse tous les dimanches, et dimanche dernier ils ... dans le parc.'::text,'ont dansé'::text,'dansent'::text,NULL::text,'Le groupe de seniors danse tous les dimanches, et dimanche dernier ils ont dansé dans le parc.'::text),
(315062,35007,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlılar grubu her pazar dans eder, geçen pazar da parkta ...'::text,'dans ettiler'::text,'dans ederler'::text,NULL::text,'Yaşlılar grubu her pazar dans eder, geçen pazar da parkta dans ettiler.'::text),
(315063,35007,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szenior csoport minden vasárnap táncol, és múlt vasárnap a parkban ...'::text,'táncoltak'::text,'táncolnak'::text,NULL::text,'A szenior csoport minden vasárnap táncol, és múlt vasárnap a parkban táncoltak.'::text),
(315066,35008,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der ältere Radfahrer ... jetzt den Parkweg entlang.'::text,'fährt'::text,'fährt'::text,'fährt'::text,'Der ältere Radfahrer fährt jetzt den Parkweg entlang.'::text),
(315070,35008,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літній велосипедист зараз ... парковою доріжкою.'::text,'їде'::text,'їде'::text,'їде'::text,'Літній велосипедист зараз їде парковою доріжкою.'::text),
(315069,35008,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ciclista mayor ... por el camino del parque ahora.'::text,'está pedaleando'::text,'pedalea'::text,'está pedaleando'::text,'El ciclista mayor está pedaleando por el camino del parque ahora.'::text),
(315068,35008,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cycliste âgé ... le long de l''allée du parc en ce moment.'::text,'est en train de rouler'::text,'roule'::text,'est en train de rouler'::text,'Le cycliste âgé est en train de rouler le long de l''allée du parc en ce moment.'::text),
(315071,35008,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı bisikletçi şu an park yolunda ...'::text,'gidiyor'::text,'gider'::text,'gidiyor'::text,'Yaşlı bisikletçi şu an park yolunda gidiyor.'::text),
(315072,35008,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idős biciklis most ... a parki ösvényen.'::text,'teker'::text,'teker'::text,'teker'::text,'Az idős biciklis most teker a parki ösvényen.'::text),
(315075,35009,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend tanzt der Seniorenkurs normalerweise drinnen, aber heute ... sie draußen.'::text,'tanzen'::text,'tanzen'::text,NULL::text,'Mädel, anscheinend tanzt der Seniorenkurs normalerweise drinnen, aber heute tanzen sie draußen.'::text),
(315079,35009,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, група літніх зазвичай танцює всередині, але сьогодні вони ... надворі.'::text,'танцюють'::text,'танцюють'::text,NULL::text,'Подруго, кажуть, група літніх зазвичай танцює всередині, але сьогодні вони танцюють надворі.'::text),
(315078,35009,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer la clase de mayores suele bailar dentro, pero hoy ellos ... fuera.'::text,'están bailando'::text,'bailan'::text,NULL::text,'Tía, al parecer la clase de mayores suele bailar dentro, pero hoy ellos están bailando fuera.'::text),
(315077,35009,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment le cours de seniors danse d''habitude à l''intérieur, mais aujourd''hui ils ... dehors.'::text,'sont en train de danser'::text,'dansent'::text,NULL::text,'Meuf, apparemment le cours de seniors danse d''habitude à l''intérieur, mais aujourd''hui ils sont en train de danser dehors.'::text),
(315080,35009,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre yaşlılar sınıfı genelde içeride dans eder ama bugün dışarıda ...'::text,'dans ediyorlar'::text,'dans ederler'::text,NULL::text,'Kızım, duyduğuma göre yaşlılar sınıfı genelde içeride dans eder ama bugün dışarıda dans ediyorlar.'::text),
(315081,35009,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a szenior csoport általában bent táncol, de ma kint ...'::text,'táncolnak'::text,'táncolnak'::text,NULL::text,'Csajszi, állítólag a szenior csoport általában bent táncol, de ma kint táncolnak.'::text),
(315084,35010,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, die älteren Tänzer sind ... als die jungen.'::text,'schneller'::text,'schneller'::text,'am schnellsten'::text,'Hör zu, er hat mir erzählt, die älteren Tänzer sind schneller als die jungen.'::text),
(315088,35010,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що літні танцюристи ... за молодих.'::text,'швидші'::text,'більш швидкі'::text,'найшвидші'::text,'Слухай, він сказав мені, що літні танцюристи швидші за молодих.'::text),
(315087,35010,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que los bailarines mayores son ... que los jóvenes.'::text,'más rápidos'::text,'más rápidos'::text,'los más rápidos'::text,'Oye, me dijo que los bailarines mayores son más rápidos que los jóvenes.'::text),
(315086,35010,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que les danseurs seniors sont ... que les jeunes.'::text,'plus rapides'::text,'plus rapides'::text,'les plus rapides'::text,'Écoute, il m''a dit que les danseurs seniors sont plus rapides que les jeunes.'::text),
(315089,35010,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana yaşlı dansçıların gençlerden ... olduğunu söyledi.'::text,'daha hızlı'::text,'daha hızlı'::text,'en hızlı'::text,'Dinle, bana yaşlı dansçıların gençlerden daha hızlı olduğunu söyledi.'::text),
(315090,35010,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy az idős táncosok ... a fiataloknál.'::text,'gyorsabbak'::text,'gyorsabbak'::text,'leggyorsabbak'::text,'Figyelj, azt mondta, hogy az idős táncosok gyorsabbak a fiataloknál.'::text),
(315093,35011,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, der ältere Mann schwingt bei jedem Spaziergang ... die Arme.'::text,'wild'::text,'wild'::text,'wild'::text,'Bestie, ich hab gehört, der ältere Mann schwingt bei jedem Spaziergang wild die Arme.'::text),
(315097,35011,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що літній чоловік на кожній прогулянці ... махає руками.'::text,'дико'::text,'дикий'::text,'дико'::text,'Подруго, я чула, що літній чоловік на кожній прогулянці дико махає руками.'::text),
(315096,35011,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que el señor mayor mueve los brazos ... en cada paseo.'::text,'salvajemente'::text,'salvaje'::text,'salvajemente'::text,'Amiga, he oído que el señor mayor mueve los brazos salvajemente en cada paseo.'::text),
(315095,35011,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire que le monsieur âgé balance les bras ... à chaque balade.'::text,'sauvagement'::text,'sauvage'::text,'sauvagement'::text,'Ma belle, j''ai entendu dire que le monsieur âgé balance les bras sauvagement à chaque balade.'::text),
(315098,35011,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki yaşlı adam her yürüyüşte kollarını ... sallıyormuş.'::text,'çılgınca'::text,'çılgın'::text,'çılgınca'::text,'Kanka, duydum ki yaşlı adam her yürüyüşte kollarını çılgınca sallıyormuş.'::text),
(315099,35011,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, azt hallottam, hogy az idős férfi minden sétán ... lóbálja a karját.'::text,'vadul'::text,'vad'::text,'vadul'::text,'Bestie, azt hallottam, hogy az idős férfi minden sétán vadul lóbálja a karját.'::text),
(308253,34251,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der weißhaarige Mann ... eine sehr glückliche Partnerin.'::text,'hat'::text,'haben'::text,'hat'::text,'Der weißhaarige Mann hat eine sehr glückliche Partnerin.'::text),
(308257,34251,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сивий чоловік ... дуже щасливу дружину.'::text,'має'::text,'мати'::text,'має'::text,'Сивий чоловік має дуже щасливу дружину.'::text),
(308256,34251,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre de pelo blanco ... una pareja muy feliz.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'El hombre de pelo blanco tiene una pareja muy feliz.'::text),
(308255,34251,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme aux cheveux blancs ... une compagne très heureuse.'::text,'a'::text,'ont'::text,'a'::text,'L''homme aux cheveux blancs a une compagne très heureuse.'::text),
(308258,34251,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz saçlı adamın çok mutlu bir eşi ...'::text,'var'::text,'var'::text,'var'::text,'Beyaz saçlı adamın çok mutlu bir eşi var.'::text),
(308259,34251,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér hajú férfinak ... egy nagyon boldog párja.'::text,'van'::text,'van'::text,'van'::text,'A fehér hajú férfinak van egy nagyon boldog párja.'::text),
(308262,34252,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alte Männer und ihre ... tanzen auf der Terrasse.'::text,'Partnerinnen'::text,'Partnerin'::text,'Partnerinnen'::text,'Alte Männer und ihre Partnerinnen tanzen auf der Terrasse.'::text),
(308266,34252,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літні чоловіки та їхні ... танцюють на терасі.'::text,'дружини'::text,'дружина'::text,'дружини'::text,'Літні чоловіки та їхні дружини танцюють на терасі.'::text),
(308265,34252,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hombres mayores y sus ... bailan en la terraza.'::text,'parejas'::text,'pareja'::text,'parejas'::text,'Hombres mayores y sus parejas bailan en la terraza.'::text),
(308264,34252,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des hommes âgés et leurs ... dansent sur la terrasse.'::text,'compagnes'::text,'compagne'::text,'compagnes'::text,'Des hommes âgés et leurs compagnes dansent sur la terrasse.'::text),
(308267,34252,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adamlar ve ... terasta dans ediyor.'::text,'eşleri'::text,'eşi'::text,'eşleri'::text,'Yaşlı adamlar ve eşleri terasta dans ediyor.'::text),
(308268,34252,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Idős férfiak és a ... táncolnak a teraszon.'::text,'párjaik'::text,'párja'::text,'párjaik'::text,'Idős férfiak és a párjaik táncolnak a teraszon.'::text),
(308271,34253,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er dreht ... Partnerin unter dem blauen Himmel.'::text,'diese'::text,'diese'::text,'jene'::text,'Er dreht diese Partnerin unter dem blauen Himmel.'::text),
(308275,34253,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він кружляє ... дружину під блакитним небом.'::text,'цю'::text,'ці'::text,'ті'::text,'Він кружляє цю дружину під блакитним небом.'::text),
(308274,34253,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace girar a ... pareja bajo el cielo azul.'::text,'esta'::text,'estas'::text,'esas'::text,'Hace girar a esta pareja bajo el cielo azul.'::text),
(308273,34253,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il fait tourner ... compagne sous le ciel bleu.'::text,'cette'::text,'ces'::text,'ces'::text,'Il fait tourner cette compagne sous le ciel bleu.'::text),
(308276,34253,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mavi gökyüzünün altında ... eşini döndürüyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Mavi gökyüzünün altında bu eşini döndürüyor.'::text),
(308277,34253,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megpörgeti ... a párját a kék ég alatt.'::text,'ezt'::text,'ezeket'::text,'azokat'::text,'Megpörgeti ezt a párját a kék ég alatt.'::text),
(308280,34254,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hält ... Partnerin an der Taille.'::text,'seine'::text,'ihre'::text,'seine'::text,'Er hält seine Partnerin an der Taille.'::text),
(308284,34254,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він тримає ... дружину за талію.'::text,'свою'::text,'свою'::text,'свою'::text,'Він тримає свою дружину за талію.'::text),
(308283,34254,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sujeta a ... pareja por la cintura.'::text,'su'::text,'su'::text,'su'::text,'Sujeta a su pareja por la cintura.'::text),
(308282,34254,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il tient ... compagne par la taille.'::text,'sa'::text,'sa'::text,'sa'::text,'Il tient sa compagne par la taille.'::text),
(308285,34254,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... eşini belinden tutuyor.'::text,'Onun'::text,'Onun'::text,'Onun'::text,'Onun eşini belinden tutuyor.'::text),
(308286,34254,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Derekánál fogva tartja a ...'::text,'párját'::text,'párját'::text,'párját'::text,'Derekánál fogva tartja a párját.'::text),
(308298,34256,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Mann und seine Partnerin ergeben ... Tänzer.'::text,'zwei'::text,'zweite'::text,'zweimal'::text,'Ein Mann und seine Partnerin ergeben zwei Tänzer.'::text),
(308302,34256,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один чоловік і його дружина — це ... танцюристи.'::text,'два'::text,'другі'::text,'двічі'::text,'Один чоловік і його дружина — це два танцюристи.'::text),
(308301,34256,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un hombre y su pareja son ... bailarines.'::text,'dos'::text,'segundos'::text,'dos veces'::text,'Un hombre y su pareja son dos bailarines.'::text),
(308300,34256,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un homme et sa compagne font ... danseurs.'::text,'deux'::text,'deuxièmes'::text,'deux fois'::text,'Un homme et sa compagne font deux danseurs.'::text),
(308303,34256,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir adam ve eşi ... dansçı eder.'::text,'iki'::text,'ikinci'::text,'iki kez'::text,'Bir adam ve eşi iki dansçı eder.'::text),
(308304,34256,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy férfi és a párja ... táncos.'::text,'két'::text,'második'::text,'kétszer'::text,'Egy férfi és a párja két táncos.'::text),
(308307,34257,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du und deine Partnerin habt so ... Style.'::text,'viel'::text,'viele'::text,'irgendwelchen'::text,'Ehrlich, du und deine Partnerin habt so viel Style.'::text),
(308311,34257,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, у тебе і твоєї дружини так ... стилю.'::text,'багато'::text,'багато'::text,'будь-якого'::text,'Чесно, у тебе і твоєї дружини так багато стилю.'::text),
(308310,34257,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tú y tu pareja tenéis ... estilo.'::text,'mucho'::text,'muchos'::text,'cualquier'::text,'La verdad, tú y tu pareja tenéis mucho estilo.'::text),
(308309,34257,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, toi et ta compagne, vous avez ... style.'::text,'beaucoup de'::text,'beaucoup de'::text,'n''importe quel'::text,'Franchement, toi et ta compagne, vous avez beaucoup de style.'::text),
(308312,34257,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen ve eşin o kadar ... tarza sahipsiniz.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Açıkçası sen ve eşin o kadar çok tarza sahipsiniz.'::text),
(308313,34257,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, neked és a párodnak olyan ... stílusotok van.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Őszintén, neked és a párodnak olyan sok stílusotok van.'::text),
(309261,34363,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ein gerahmtes Foto ihrer Familie.'::text,'hat'::text,'haben'::text,'hat'::text,'Sie hat ein gerahmtes Foto ihrer Familie.'::text),
(309265,34363,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... фотографію своєї родини в рамці.'::text,'має'::text,'мати'::text,'має'::text,'Вона має фотографію своєї родини в рамці.'::text),
(309264,34363,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... una fotografía enmarcada de su familia.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Ella tiene una fotografía enmarcada de su familia.'::text),
(309263,34363,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... une photographie encadrée de sa famille.'::text,'a'::text,'ont'::text,'a'::text,'Elle a une photographie encadrée de sa famille.'::text),
(309266,34363,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun ailesinin çerçeveli bir fotoğrafı ...'::text,'var'::text,'var'::text,'var'::text,'Onun ailesinin çerçeveli bir fotoğrafı var.'::text),
