(309279,34365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Foto und eine Vase: ... Foto kommt zuerst.'::text,'das'::text,'ein'::text,'ein'::text,'Ein Foto und eine Vase: das Foto kommt zuerst.'::text),
(309283,34365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фотографія і ваза: ... фотографія йде першою.'::text,''::text,NULL::text,NULL::text,'Фотографія і ваза: фотографія йде першою.'::text),
(309282,34365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una fotografía y un jarrón: ... fotografía va primero.'::text,'la'::text,'una'::text,'una'::text,'Una fotografía y un jarrón: la fotografía va primero.'::text),
(309281,34365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une photographie et un vase : ... photographie passe en premier.'::text,'la'::text,'une'::text,'une'::text,'Une photographie et un vase : la photographie passe en premier.'::text),
(309284,34365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir fotoğraf ve bir vazo: ... fotoğraf önce geliyor.'::text,''::text,'bir'::text,'bir'::text,'Bir fotoğraf ve bir vazo: fotoğraf önce geliyor.'::text),
(309285,34365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy fotó és egy váza: ... fotó megy előre.'::text,'a'::text,'egy'::text,'egy'::text,'Egy fotó és egy váza: a fotó megy előre.'::text),
(309288,34366,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Foto hat einen Rahmen, also ist es gerahmt.'::text,'Dieses'::text,'Diese'::text,'Jene'::text,'Dieses Foto hat einen Rahmen, also ist es gerahmt.'::text),
(309292,34366,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... фотографія має рамку, тож вона в рамці.'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Ця фотографія має рамку, тож вона в рамці.'::text),
(309291,34366,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fotografía tiene marco, así que está enmarcada.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta fotografía tiene marco, así que está enmarcada.'::text),
(309290,34366,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... photographie a un cadre, donc elle est encadrée.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette photographie a un cadre, donc elle est encadrée.'::text),
(309293,34366,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fotoğrafın çerçevesi var, yani çerçeveli.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu fotoğrafın çerçevesi var, yani çerçeveli.'::text),
(309294,34366,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a fotónak van kerete, tehát be van keretezve.'::text,'Ennek'::text,'Ezeknek'::text,'Azoknak'::text,'Ennek a fotónak van kerete, tehát be van keretezve.'::text),
(309297,34367,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du stellst ... Familienfoto ganz nach vorne. Smooth.'::text,'dein'::text,'du'::text,'deins'::text,'Du stellst dein Familienfoto ganz nach vorne. Smooth.'::text),
(309301,34367,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ставиш ... сімейне фото на самий перед. Стильно.'::text,'своє'::text,'ти'::text,'твоє'::text,'Ти ставиш своє сімейне фото на самий перед. Стильно.'::text),
(309300,34367,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pones ... foto familiar justo delante. Qué estilo.'::text,'tu'::text,'tú'::text,'tuya'::text,'Pones tu foto familiar justo delante. Qué estilo.'::text),
(309299,34367,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu mets ... photo de famille juste devant. Classe.'::text,'ta'::text,'toi'::text,'la tienne'::text,'Tu mets ta photo de famille juste devant. Classe.'::text),
(309302,34367,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... aile fotoğrafını tam öne koyuyorsun. Çok şık.'::text,'Senin'::text,'Sen'::text,'Seninki'::text,'Senin aile fotoğrafını tam öne koyuyorsun. Çok şık.'::text),
(309303,34367,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Legelőre teszed a családi ... Ügyes.'::text,'fotódat'::text,'te'::text,'a tiédet'::text,'Legelőre teszed a családi fotódat Ügyes.'::text),
(309306,34368,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du stellst ein Foto dazu und so viel ... Beeindruckend.'::text,'Stil.'::text,'Stil.'::text,'Fotos.'::text,'Du stellst ein Foto dazu und so viel Stil. Beeindruckend.'::text),
(309310,34368,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти додаєш одне фото і стільки ... Вражає.'::text,'стилю.'::text,'стилю.'::text,'фотографій.'::text,'Ти додаєш одне фото і стільки стилю. Вражає.'::text),
(309309,34368,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Añades una foto y tanto ... Impresionante.'::text,'estilo.'::text,'estilo.'::text,'fotos.'::text,'Añades una foto y tanto estilo. Impresionante.'::text),
(309308,34368,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ajoutes une photo et tellement de ... Impressionnant.'::text,'style.'::text,'style.'::text,'photos.'::text,'Tu ajoutes une photo et tellement de style. Impressionnant.'::text),
(309311,34368,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir fotoğraf ekliyorsun ve o kadar çok ... Etkilendim.'::text,'tarz.'::text,'tarzlar.'::text,'fotoğraflar.'::text,'Bir fotoğraf ekliyorsun ve o kadar çok tarz. Etkilendim.'::text),
(309312,34368,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hozzáteszel egy fotót, és annyi ... Le vagyok nyűgözve.'::text,'stílus.'::text,'stílus.'::text,'fotó.'::text,'Hozzáteszel egy fotót, és annyi stílus. Le vagyok nyűgözve.'::text),
(309315,34369,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dein Regal sieht super aus mit ... Fotos und Pflanzen.'::text,'einigen'::text,'irgendwelchen'::text,'viel'::text,'Ehrlich, dein Regal sieht super aus mit einigen Fotos und Pflanzen.'::text),
(309319,34369,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твоя полиця виглядає класно з ... фотографіями й рослинами.'::text,'кількома'::text,'будь-якими'::text,'багатьма'::text,'Чесно, твоя полиця виглядає класно з кількома фотографіями й рослинами.'::text),
(309318,34369,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tu estantería queda genial con ... fotos y plantas.'::text,'algunas'::text,'cualquier'::text,'mucha'::text,'La verdad, tu estantería queda genial con algunas fotos y plantas.'::text),
(309317,34369,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ton étagère est top avec ... photos et plantes.'::text,'des'::text,'n''importe quelles'::text,'beaucoup de'::text,'Franchement, ton étagère est top avec des photos et plantes.'::text),
(309320,34369,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası rafın ... fotoğraf ve bitkiyle harika görünüyor.'::text,'birkaç'::text,'herhangi'::text,'çok'::text,'Açıkçası rafın birkaç fotoğraf ve bitkiyle harika görünüyor.'::text),
(309321,34369,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a polcod szuperül néz ki ... fotóval és növénnyel.'::text,'néhány'::text,'bármilyen'::text,'sok'::text,'Őszintén, a polcod szuperül néz ki néhány fotóval és növénnyel.'::text),
(298128,33126,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie liegt ... der Matte mit ihrem Gewehr.'::text,'auf'::text,'in'::text,'an'::text,'Sie liegt auf der Matte mit ihrem Gewehr.'::text),
(298132,33126,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона лежить ... килимку зі своєю гвинтівкою.'::text,'на'::text,'у'::text,'біля'::text,'Вона лежить на килимку зі своєю гвинтівкою.'::text),
(298131,33126,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está tumbada ... la esterilla con su arma.'::text,'sobre'::text,'en'::text,'a'::text,'Está tumbada sobre la esterilla con su arma.'::text),
(298130,33126,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est allongée ... le tapis avec son fusil.'::text,'sur'::text,'dans'::text,'à'::text,'Elle est allongée sur le tapis avec son fusil.'::text),
(298133,33126,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüfeğiyle birlikte matın ... yatıyor.'::text,'üstünde'::text,'içinde'::text,NULL::text,'Tüfeğiyle birlikte matın üstünde yatıyor.'::text),
(298134,33126,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ... fekszik a fegyverével.'::text,'szőnyegen'::text,'szőnyegben'::text,'szőnyegnél'::text,'A szőnyegen fekszik a fegyverével.'::text),
(298146,33128,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau dich an, du ... so ruhig mit deinem Gewehr. Respekt.'::text,'zielst'::text,'zielst'::text,'zielst'::text,'Schau dich an, du zielst so ruhig mit deinem Gewehr. Respekt.'::text),
(298150,33128,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ну ти даєш, ти ... зі своєї гвинтівки так спокійно. Респект.'::text,'цілишся'::text,'цілишся'::text,'цілишся'::text,'Ну ти даєш, ти цілишся зі своєї гвинтівки так спокійно. Респект.'::text),
(298149,33128,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mírate, tú ... con tu arma con tanta calma. Respeto.'::text,'estás apuntando'::text,'apunta'::text,'estás apuntando'::text,'Mírate, tú estás apuntando con tu arma con tanta calma. Respeto.'::text),
(298148,33128,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde-toi, tu ... avec ton fusil si calmement. Respect.'::text,'es en train de viser'::text,'vise'::text,'es en train de viser'::text,'Regarde-toi, tu es en train de viser avec ton fusil si calmement. Respect.'::text),
(298151,33128,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şuna bak, tüfeğinle öyle sakin ... Saygılar.'::text,'nişan alıyorsun'::text,'nişan alır'::text,'nişan alıyorsun'::text,'Şuna bak, tüfeğinle öyle sakin nişan alıyorsun Saygılar.'::text),
(298152,33128,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézzenek oda, olyan nyugodtan ... a fegyvereddel. Respekt.'::text,'célzol'::text,'célzol'::text,'célzol'::text,'Nézzenek oda, olyan nyugodtan célzol a fegyvereddel. Respekt.'::text),
(298164,33130,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, das Gewehr ... die ganze Arbeit machen, logisch.'::text,'wird'::text,'wird'::text,'wird'::text,'Klar, das Gewehr wird die ganze Arbeit machen, logisch.'::text),
(298168,33130,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ага, гвинтівка ... всю роботу, звісно.'::text,'зробить'::text,'зробить'::text,'зробить'::text,'Ага, гвинтівка зробить всю роботу, звісно.'::text),
(298167,33130,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claro, el arma ... todo el trabajo, obviamente.'::text,'hará'::text,'hará'::text,'hará'::text,'Claro, el arma hará todo el trabajo, obviamente.'::text),
(298166,33130,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bien sûr, le fusil ... tout le travail, évidemment.'::text,'fera'::text,'fera'::text,'fera'::text,'Bien sûr, le fusil fera tout le travail, évidemment.'::text),
(298169,33130,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii, bütün işi tüfek ..., belli ki.'::text,'yapacak'::text,'yapacak'::text,'yapacak'::text,'Tabii, bütün işi tüfek yapacak, belli ki.'::text),
(298170,33130,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Persze, az egész munkát a fegyver ..., nyilván.'::text,'fogja elvégezni'::text,'fogja elvégezni'::text,'fogja elvégezni'::text,'Persze, az egész munkát a fegyver fogja elvégezni, nyilván.'::text),
(298173,33131,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie liegt auf der Matte. Sie ... mit ihrem Gewehr schießen.'::text,'wird'::text,'wird'::text,'wird'::text,'Sie liegt auf der Matte. Sie wird mit ihrem Gewehr schießen.'::text),
(298177,33131,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона лежить на килимку. Вона ... вистрілити з гвинтівки.'::text,'збирається'::text,'збирається'::text,'збирається'::text,'Вона лежить на килимку. Вона збирається вистрілити з гвинтівки.'::text),
(298176,33131,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está tumbada en la esterilla. Ella ... disparar su arma.'::text,'va a'::text,'va a'::text,'va a'::text,'Está tumbada en la esterilla. Ella va a disparar su arma.'::text),
(298175,33131,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est allongée sur le tapis. Elle ... tirer avec son fusil.'::text,'va'::text,'va'::text,'va'::text,'Elle est allongée sur le tapis. Elle va tirer avec son fusil.'::text),
(298178,33131,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Matın üstünde yatıyor. Tüfeğiyle ...'::text,'ateş edecek'::text,'ateş edecek'::text,'ateş edecek'::text,'Matın üstünde yatıyor. Tüfeğiyle ateş edecek.'::text),
(298179,33131,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szőnyegen fekszik. A fegyverével ... lőni.'::text,'fog'::text,'fog'::text,'fog'::text,'A szőnyegen fekszik. A fegyverével fog lőni.'::text),
(298182,33132,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie zielt mit dem Gewehr auf die Scheibe. Sie ... schießen.'::text,'wird'::text,'wird'::text,NULL::text,'Sie zielt mit dem Gewehr auf die Scheibe. Sie wird schießen.'::text),
(298186,33132,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона цілиться з гвинтівки в мішень. Вона ...'::text,'збирається вистрілити'::text,'вистрілить'::text,NULL::text,'Вона цілиться з гвинтівки в мішень. Вона збирається вистрілити.'::text),
(298185,33132,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apunta su arma al blanco. Ella ...'::text,'va a disparar'::text,'disparará'::text,NULL::text,'Apunta su arma al blanco. Ella va a disparar.'::text),
(298184,33132,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle vise la cible avec son fusil. Elle ...'::text,'va tirer'::text,'tirera'::text,NULL::text,'Elle vise la cible avec son fusil. Elle va tirer.'::text),
(298187,33132,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüfeğiyle hedefe nişan alıyor. ...'::text,'Ateş edecek'::text,'Ateş edecek'::text,NULL::text,'Tüfeğiyle hedefe nişan alıyor. Ateş edecek.'::text),
(298188,33132,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fegyverével a célpontra céloz. ...'::text,'Lőni fog'::text,'Lőni fog'::text,NULL::text,'A fegyverével a célpontra céloz. Lőni fog.'::text),
(298191,33133,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend brauchte sie nicht viel ..., um mit dem Gewehr zu schießen.'::text,'Hilfe'::text,'Hilfe'::text,'eine Hilfe'::text,'Mädel, anscheinend brauchte sie nicht viel Hilfe, um mit dem Gewehr zu schießen.'::text),
(298195,33133,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, їй не знадобилося багато ..., щоб вистрілити з тієї гвинтівки.'::text,'допомоги'::text,'допомоги'::text,'допомоги'::text,'Подруго, кажуть, їй не знадобилося багато допомоги, щоб вистрілити з тієї гвинтівки.'::text),
(298194,33133,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer no necesitó mucha ... para disparar esa arma.'::text,'ayuda'::text,'ayuda'::text,'una ayuda'::text,'Tía, al parecer no necesitó mucha ayuda para disparar esa arma.'::text),
(298193,33133,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle n''a pas eu besoin de beaucoup d''... pour tirer avec ce fusil.'::text,'aide'::text,'aide'::text,'une aide'::text,'Meuf, apparemment elle n''a pas eu besoin de beaucoup d''aide pour tirer avec ce fusil.'::text),
(298196,33133,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre o tüfeği ateşlemek için çok ... ihtiyacı olmamış.'::text,'yardıma'::text,'yardımlara'::text,'bir yardıma'::text,'Kızım, duyduğuma göre o tüfeği ateşlemek için çok yardıma ihtiyacı olmamış.'::text),
(298197,33133,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag nem kellett neki sok ... ahhoz, hogy elsüsse azt a fegyvert.'::text,'segítség'::text,'segítség'::text,'egy segítség'::text,'Csajszi, állítólag nem kellett neki sok segítség ahhoz, hogy elsüsse azt a fegyvert.'::text),
(321285,35699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie ... so viele Cerealien. Der Supermarkt ist gleich leer!'::text,'hat'::text,'haben'::text,'hat'::text,'Alter, sie hat so viele Cerealien. Der Supermarkt ist gleich leer!'::text),
(321289,35699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... стільки пластівців. Супермаркет буде порожній!'::text,'має'::text,'мати'::text,'має'::text,'Бро, вона має стільки пластівців. Супермаркет буде порожній!'::text),
(321288,35699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... un montón de cereales. ¡El supermercado se va a quedar vacío!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Tío, ella tiene un montón de cereales. ¡El supermercado se va a quedar vacío!'::text),
(321287,35699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... tellement de céréales. Le supermarché va être vide !'::text,'a'::text,'ont'::text,'a'::text,'Frérot, elle a tellement de céréales. Le supermarché va être vide !'::text),
(321290,35699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun bir sürü mısır gevreği ... Süpermarket boşalacak!'::text,'var'::text,'var'::text,'var'::text,'Kanka, onun bir sürü mısır gevreği var Süpermarket boşalacak!'::text),
(321291,35699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, neki ... annyi gabonapehelye. A szupermarket ki fog ürülni!'::text,'van'::text,'van'::text,'van'::text,'Tesó, neki van annyi gabonapehelye. A szupermarket ki fog ürülni!'::text),
(321294,35700,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Alter, sie kauft in diesem Supermarkt gleich ... Cerealien.'::text,'40 Packungen'::text,'40 Packung'::text,'40 Packungen'::text,'Nee, Alter, sie kauft in diesem Supermarkt gleich 40 Packungen Cerealien.'::text),
