(323906,35990,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... laver toute la tour d''assiettes ce soir.'::text,'va'::text,'vont'::text,'va'::text,'Meuf, apparemment elle va laver toute la tour d''assiettes ce soir.'::text),
(323909,35990,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre bu akşam bütün tabak kulesini ...'::text,'yıkayacak'::text,'yıkayacaklar'::text,'yıkayacak'::text,'Kızım, duyduğuma göre bu akşam bütün tabak kulesini yıkayacak.'::text),
(323910,35990,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ma este el ... mosni az egész tányértornyot.'::text,'fogja'::text,'fogják'::text,'fogja'::text,'Csajszi, állítólag ma este el fogja mosni az egész tányértornyot.'::text),
(323922,35992,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, dieser Tellerturm braucht gleich so viel ..., echt.'::text,'Wasser'::text,'Wasser'::text,'ein Wasser'::text,'Alter, dieser Tellerturm braucht gleich so viel Wasser, echt.'::text),
(323926,35992,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, тій вежі з тарілок треба буде стільки ..., чесно.'::text,'води'::text,'вод'::text,'води'::text,'Бро, тій вежі з тарілок треба буде стільки води, чесно.'::text),
(323925,35992,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, esa torre de platos va a necesitar tanta ..., en serio.'::text,'agua'::text,'agua'::text,'un agua'::text,'Tío, esa torre de platos va a necesitar tanta agua, en serio.'::text),
(323924,35992,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, cette tour d''assiettes va demander tellement d''..., sérieux.'::text,'eau'::text,'eau'::text,'une eau'::text,'Frérot, cette tour d''assiettes va demander tellement d''eau, sérieux.'::text),
(323927,35992,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o tabak kulesine o kadar çok ... lazım olacak ki, cidden.'::text,'su'::text,'sular'::text,'bir su'::text,'Kanka, o tabak kulesine o kadar çok su lazım olacak ki, cidden.'::text),
(323928,35992,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, annak a tányértoronynak annyi ... kell majd, komolyan.'::text,'víz'::text,'víz'::text,'egy víz'::text,'Tesó, annak a tányértoronynak annyi víz kell majd, komolyan.'::text),
(323931,35993,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Turm hat ... Teller, also spült sie eine Stunde lang.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Der Turm hat viele Teller, also spült sie eine Stunde lang.'::text),
(323935,35993,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У вежі ... тарілок, тож вона миє цілу годину.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'У вежі багато тарілок, тож вона миє цілу годину.'::text),
(323934,35993,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La torre tiene ... platos, así que friega durante una hora.'::text,'muchos'::text,'mucho'::text,'cualquier'::text,'La torre tiene muchos platos, así que friega durante una hora.'::text),
(323933,35993,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tour a ... assiettes, alors elle fait la vaisselle pendant une heure.'::text,'beaucoup d'''::text,'beaucoup d'''::text,'n''importe quelles'::text,'La tour a beaucoup d'' assiettes, alors elle fait la vaisselle pendant une heure.'::text),
(323936,35993,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kulede ... tabak var, bu yüzden bir saat boyunca yıkıyor.'::text,'çok'::text,'çok'::text,'herhangi'::text,'Kulede çok tabak var, bu yüzden bir saat boyunca yıkıyor.'::text),
(323937,35993,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A toronyban ... tányér van, ezért egy órán át mosogat.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'A toronyban sok tányér van, ezért egy órán át mosogat.'::text),
(323940,35994,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... ein hoher Tellerturm in der Spüle.'::text,'ist'::text,'sind'::text,'sein'::text,'Da ist ein hoher Tellerturm in der Spüle.'::text),
(323944,35994,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У раковині ... висока вежа з тарілок.'::text,'є'::text,'є'::text,'бути'::text,'У раковині є висока вежа з тарілок.'::text),
(323943,35994,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una torre alta de platos en el fregadero.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay una torre alta de platos en el fregadero.'::text),
(323942,35994,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... une haute tour d''assiettes dans l''évier.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a une haute tour d''assiettes dans l''évier.'::text),
(323945,35994,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lavaboda yüksek bir tabak kulesi ...'::text,'var'::text,'var'::text,'olmak'::text,'Lavaboda yüksek bir tabak kulesi var.'::text),
(323946,35994,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mosogatóban ... egy magas tányértorony.'::text,'van'::text,'vannak'::text,'lenni'::text,'A mosogatóban van egy magas tányértorony.'::text),
(323949,35995,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genial, eindeutig: Der Turm ist riesig, ... die Spüle ist winzig.'::text,'aber'::text,'also'::text,'weil'::text,'Genial, eindeutig: Der Turm ist riesig, aber die Spüle ist winzig.'::text),
(323953,35995,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Геніально, звісно: вежа величезна, ... раковина крихітна.'::text,'але'::text,'тому'::text,'бо'::text,'Геніально, звісно: вежа величезна, але раковина крихітна.'::text),
(323952,35995,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genial, está claro: la torre es enorme, ... el fregadero es diminuto.'::text,'pero'::text,'así que'::text,'porque'::text,'Genial, está claro: la torre es enorme, pero el fregadero es diminuto.'::text),
(323951,35995,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Génial, clairement : la tour est énorme, ... l''évier est minuscule.'::text,'mais'::text,'donc'::text,'parce que'::text,'Génial, clairement : la tour est énorme, mais l''évier est minuscule.'::text),
(323954,35995,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dahice tabii: kule devasa ... lavabo minicik.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Dahice tabii: kule devasa ama lavabo minicik.'::text),
(323955,35995,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zseniális, egyértelműen: a torony hatalmas, ... a mosogató pici.'::text,'de'::text,'ezért'::text,'mert'::text,'Zseniális, egyértelműen: a torony hatalmas, de a mosogató pici.'::text),
(321393,35711,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... am Sweatshirt, weil sie es will.'::text,'zieht'::text,'ziehen'::text,'ziehend'::text,'Sie zieht am Sweatshirt, weil sie es will.'::text),
(321397,35711,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... світшот, бо хоче його.'::text,'тягне'::text,'тягнути'::text,'тягнучи'::text,'Вона тягне світшот, бо хоче його.'::text),
(321396,35711,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... de la sudadera porque la quiere.'::text,'tira'::text,'tirar'::text,'tirando'::text,'Ella tira de la sudadera porque la quiere.'::text),
(321395,35711,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sur le sweat-shirt parce qu''elle le veut.'::text,'tire'::text,'tirer'::text,'tirant'::text,'Elle tire sur le sweat-shirt parce qu''elle le veut.'::text),
(321398,35711,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sweatshirt''ü istediği için ...'::text,'çeker'::text,'çekmek'::text,'çekerek'::text,'Sweatshirt''ü istediği için çeker.'::text),
(321399,35711,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a pulcsit, mert kell neki.'::text,'Húzza'::text,'Húzni'::text,'Húzó'::text,'Húzza a pulcsit, mert kell neki.'::text),
(321402,35712,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nur ein Mädchen ... das lila Sweatshirt tragen.'::text,'kann'::text,NULL::text,'sind'::text,'Nur ein Mädchen kann das lila Sweatshirt tragen.'::text),
(321406,35712,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише одна дівчина ... носити бузковий світшот.'::text,'може'::text,NULL::text,'є'::text,'Лише одна дівчина може носити бузковий світшот.'::text),
(321405,35712,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo una chica ... llevar la sudadera lila.'::text,'puede'::text,NULL::text,'están'::text,'Solo una chica puede llevar la sudadera lila.'::text),
(321404,35712,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une seule fille ... porter le sweat-shirt lilas.'::text,'peut'::text,NULL::text,'sont'::text,'Une seule fille peut porter le sweat-shirt lilas.'::text),
(321407,35712,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lila sweatshirt''ü sadece bir kız ...'::text,'giyebilir'::text,NULL::text,NULL::text,'Lila sweatshirt''ü sadece bir kız giyebilir.'::text),
(321408,35712,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak egy lány ... a lila pulcsit.'::text,'hordhatja'::text,NULL::text,'vannak'::text,'Csak egy lány hordhatja a lila pulcsit.'::text),
(321411,35713,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Freundinnen ziehen an einem lila Sweatshirt. Sie brauchen ...'::text,'2 Sweatshirts.'::text,'2 Sweatshirt.'::text,'2 Sweatshirts.'::text,'Die Freundinnen ziehen an einem lila Sweatshirt. Sie brauchen 2 Sweatshirts.'::text),
(321415,35713,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруги тягнуть один бузковий світшот. Їм потрібні ...'::text,'2 світшоти.'::text,'2 світшот.'::text,'2 світшоти.'::text,'Подруги тягнуть один бузковий світшот. Їм потрібні 2 світшоти.'::text),
(321414,35713,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las amigas tiran de una sudadera lila. Necesitan ...'::text,'2 sudaderas.'::text,'2 sudadera.'::text,'2 sudaderas.'::text,'Las amigas tiran de una sudadera lila. Necesitan 2 sudaderas.'::text),
(321413,35713,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les copines tirent sur un seul sweat-shirt lilas. Il leur faut ...'::text,'2 sweat-shirts.'::text,'2 sweat-shirt.'::text,'2 sweat-shirts.'::text,'Les copines tirent sur un seul sweat-shirt lilas. Il leur faut 2 sweat-shirts.'::text),
(321416,35713,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlar tek bir lila sweatshirt''ü çekiştiriyor. İhtiyaçları olan ...'::text,'2 sweatshirt.'::text,'2 sweatshirt.'::text,'2 sweatshirt.'::text,'Arkadaşlar tek bir lila sweatshirt''ü çekiştiriyor. İhtiyaçları olan 2 sweatshirt.'::text),
(321417,35713,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátnők egyetlen lila pulcsit húzkodnak. Kellene nekik ...'::text,'2 pulcsi.'::text,'2 pulcsi.'::text,'2 pulcsi.'::text,'A barátnők egyetlen lila pulcsit húzkodnak. Kellene nekik 2 pulcsi.'::text),
(321420,35714,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie haben ein Sweatshirt. Beide Mädchen ziehen an ... Sweatshirt.'::text,'dem'::text,'einem'::text,'einem'::text,'Sie haben ein Sweatshirt. Beide Mädchen ziehen an dem Sweatshirt.'::text),
(321424,35714,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У них є світшот. Обидві дівчини тягнуть ... світшот.'::text,''::text,NULL::text,NULL::text,'У них є світшот. Обидві дівчини тягнуть світшот.'::text),
(321423,35714,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tienen una sudadera. Las dos chicas tiran de ... sudadera.'::text,'la'::text,'una'::text,'una'::text,'Tienen una sudadera. Las dos chicas tiran de la sudadera.'::text),
(321422,35714,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ont un sweat-shirt. Les deux filles tirent sur ... sweat-shirt.'::text,'le'::text,'un'::text,'un'::text,'Elles ont un sweat-shirt. Les deux filles tirent sur le sweat-shirt.'::text),
(321425,35714,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sweatshirt''leri var. İki kız da ... sweatshirt''ü çekiyor.'::text,''::text,'bir'::text,'bir'::text,'Bir sweatshirt''leri var. İki kız da sweatshirt''ü çekiyor.'::text),
(321426,35714,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van egy pulcsijuk. Mindkét lány húzza ... pulcsit.'::text,'a'::text,'egy'::text,'egy'::text,'Van egy pulcsijuk. Mindkét lány húzza a pulcsit.'::text),
(321429,35715,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... lila Sweatshirt ist weich und warm.'::text,'Dieses'::text,'Diese'::text,'Jene'::text,'Dieses lila Sweatshirt ist weich und warm.'::text),
(321433,35715,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... бузковий світшот м''який і теплий.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей бузковий світшот м''який і теплий.'::text),
(321432,35715,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sudadera lila es suave y calentita.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta sudadera lila es suave y calentita.'::text),
(321431,35715,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sweat-shirt lilas est doux et chaud.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce sweat-shirt lilas est doux et chaud.'::text),
(321434,35715,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... lila sweatshirt yumuşak ve sıcak.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu lila sweatshirt yumuşak ve sıcak.'::text),
(321435,35715,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a lila pulcsi puha és meleg.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a lila pulcsi puha és meleg.'::text),
(321438,35716,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, gib mir ... Sweatshirt zurück, das ist meins!'::text,'mein'::text,'mich'::text,'ich'::text,'Nee, gib mir mein Sweatshirt zurück, das ist meins!'::text),
(321442,35716,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, поверни мені ... світшот, він мій!'::text,'мій'::text,'мене'::text,'я'::text,'Не, поверни мені мій світшот, він мій!'::text),
(321441,35716,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nah, devuélveme ... sudadera, es mía!'::text,'mi'::text,'me'::text,'yo'::text,'¡Nah, devuélveme mi sudadera, es mía!'::text),
(321440,35716,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, rends-moi ... sweat-shirt, c''est le mien !'::text,'mon'::text,'moi'::text,'je'::text,'Nan, rends-moi mon sweat-shirt, c''est le mien !'::text),
(321443,35716,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, ... sweatshirt''ümü geri ver, o benim!'::text,'benim'::text,'beni'::text,'ben'::text,'Yok, benim sweatshirt''ümü geri ver, o benim!'::text),
(321444,35716,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, add vissza a ..., az enyém!'::text,'pulcsimat'::text,'engem'::text,'én'::text,'Á, add vissza a pulcsimat, az enyém!'::text),
(321447,35717,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ... kriegt das Sweatshirt? Das wird ein langer Kampf.'::text,'wer'::text,'wo'::text,'wann'::text,'Alter, wer kriegt das Sweatshirt? Das wird ein langer Kampf.'::text),
(321451,35717,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... отримає світшот? Це буде довга битва.'::text,'хто'::text,'де'::text,'коли'::text,'Бро, хто отримає світшот? Це буде довга битва.'::text),
(321450,35717,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... se queda la sudadera? Va a ser una pelea larga.'::text,'quién'::text,'dónde'::text,'cuándo'::text,'Tío, ¿quién se queda la sudadera? Va a ser una pelea larga.'::text),
(321449,35717,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ... récupère le sweat-shirt ? Ça va être un long combat.'::text,'qui'::text,'où'::text,'quand'::text,'Frérot, qui récupère le sweat-shirt ? Ça va être un long combat.'::text),
(321452,35717,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, sweatshirt''ü ... alacak? Uzun bir kavga olacak.'::text,'kim'::text,'nerede'::text,'ne zaman'::text,'Kanka, sweatshirt''ü kim alacak? Uzun bir kavga olacak.'::text),
(321453,35717,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... kapja meg a pulcsit? Hosszú harc lesz.'::text,'ki'::text,'hol'::text,'mikor'::text,'Tesó, ki kapja meg a pulcsit? Hosszú harc lesz.'::text),
(316587,35177,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Es gibt keine Ruhe ... diesem Wohnzimmer!'::text,'in'::text,'auf'::text,'an'::text,'Albtraum! Es gibt keine Ruhe in diesem Wohnzimmer!'::text),
(316591,35177,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! ... цій вітальні немає тиші!'::text,'У'::text,'На'::text,'Біля'::text,'Жах! У цій вітальні немає тиші!'::text),
(316590,35177,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡No hay silencio ... este salón!'::text,'en'::text,'sobre'::text,'a'::text,'¡Pesadilla! ¡No hay silencio en este salón!'::text),
(316589,35177,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Il n''y a aucun silence ... ce salon !'::text,'dans'::text,'sur'::text,'à'::text,'Cauchemar ! Il n''y a aucun silence dans ce salon !'::text),
(316592,35177,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Bu oturma odasının ... hiç sessizlik yok!'::text,'içinde'::text,'üstünde'::text,NULL::text,'Kâbus! Bu oturma odasının içinde hiç sessizlik yok!'::text),
(316593,35177,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Nincs csend ebben a ...!'::text,'nappaliban'::text,'nappalin'::text,'nappalinál'::text,'Rémálom! Nincs csend ebben a nappaliban!'::text),
(316605,35179,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... die Stille auf der Übernachtungsparty sehr schnell.'::text,'endete'::text,'endet'::text,'enden'::text,'Gestern Abend endete die Stille auf der Übernachtungsparty sehr schnell.'::text),
(316609,35179,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ввечері тиша на ночівці ... дуже швидко.'::text,'закінчилася'::text,'закінчується'::text,'закінчуватися'::text,'Учора ввечері тиша на ночівці закінчилася дуже швидко.'::text),
(316608,35179,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche el silencio ... muy rápido en la fiesta de pijamas.'::text,'acabó'::text,'acaba'::text,'acabar'::text,'Anoche el silencio acabó muy rápido en la fiesta de pijamas.'::text),
(316607,35179,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, le silence ... très vite à la soirée pyjama.'::text,'a pris fin'::text,'prend fin'::text,'prendre fin'::text,'Hier soir, le silence a pris fin très vite à la soirée pyjama.'::text),
(316610,35179,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün gece pijama partisinde sessizlik çok çabuk ...'::text,'bitti'::text,'biter'::text,'bitmek'::text,'Dün gece pijama partisinde sessizlik çok çabuk bitti.'::text),
(316611,35179,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este a csend nagyon gyorsan ... a pizsamapartin.'::text,'véget ért'::text,'véget ér'::text,'véget érni'::text,'Tegnap este a csend nagyon gyorsan véget ért a pizsamapartin.'::text),
(316614,35180,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Stille, klar: Normalerweise flüstern sie, aber gestern ... sie die ganze Nacht.'::text,'schrien'::text,'schreien'::text,NULL::text,'Tolle Stille, klar: Normalerweise flüstern sie, aber gestern schrien sie die ganze Nacht.'::text),
(316618,35180,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова тиша, звісно: зазвичай вони шепочуться, але вчора вони ... всю ніч.'::text,'кричали'::text,'кричать'::text,NULL::text,'Чудова тиша, звісно: зазвичай вони шепочуться, але вчора вони кричали всю ніч.'::text),
(316617,35180,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué silencio, obviamente: normalmente susurran, pero ayer ellas ... toda la noche.'::text,'gritaron'::text,'gritan'::text,NULL::text,'Qué silencio, obviamente: normalmente susurran, pero ayer ellas gritaron toda la noche.'::text),
(316616,35180,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super silence, évidemment : d''habitude elles chuchotent, mais hier elles ... toute la nuit.'::text,'ont crié'::text,'crient'::text,NULL::text,'Super silence, évidemment : d''habitude elles chuchotent, mais hier elles ont crié toute la nuit.'::text),
(316619,35180,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika sessizlik tabii: genelde fısıldaşırlar ama dün bütün gece ...'::text,'bağırdılar'::text,'bağırırlar'::text,NULL::text,'Harika sessizlik tabii: genelde fısıldaşırlar ama dün bütün gece bağırdılar.'::text),
(316620,35180,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek csend, nyilván: általában suttognak, de tegnap egész éjjel ...'::text,'kiabáltak'::text,'kiabálnak'::text,NULL::text,'Remek csend, nyilván: általában suttognak, de tegnap egész éjjel kiabáltak.'::text),
(316623,35181,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Alter, die Stille ist hinüber. Alle ... gleichzeitig.'::text,'schreien'::text,'schreiend'::text,'schreien'::text,'Nee, Alter, die Stille ist hinüber. Alle schreien gleichzeitig.'::text),
(316627,35181,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, тиші кінець. Усі ... одночасно.'::text,'кричать'::text,'кричачи'::text,'кричать'::text,'Не, бро, тиші кінець. Усі кричать одночасно.'::text),
(316626,35181,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, el silencio está muerto. Todo el mundo ... a la vez.'::text,'está gritando'::text,'gritando'::text,'está gritando'::text,'Qué va, tío, el silencio está muerto. Todo el mundo está gritando a la vez.'::text),
(316625,35181,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, le silence est mort. Tout le monde ... en même temps.'::text,'est en train de crier'::text,'criant'::text,'est en train de crier'::text,'Nan frérot, le silence est mort. Tout le monde est en train de crier en même temps.'::text),
(316628,35181,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, sessizlik bitti. Herkes aynı anda ...'::text,'bağırıyor'::text,'bağırarak'::text,'bağırıyor'::text,'Yok kanka, sessizlik bitti. Herkes aynı anda bağırıyor.'::text),
(316629,35181,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, a csendnek annyi. Mindenki egyszerre ...'::text,'kiabál'::text,'kiabálva'::text,'kiabál'::text,'Á, tesó, a csendnek annyi. Mindenki egyszerre kiabál.'::text),
(316632,35182,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Alter, normalerweise mögen sie Stille, aber jetzt ... sie wie verrückt.'::text,'kreischen'::text,'kreischen'::text,NULL::text,'Nee, Alter, normalerweise mögen sie Stille, aber jetzt kreischen sie wie verrückt.'::text),
(316636,35182,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, зазвичай вони люблять тишу, але зараз вони ... як божевільні.'::text,'верещать'::text,'верещать'::text,NULL::text,'Не, бро, зазвичай вони люблять тишу, але зараз вони верещать як божевільні.'::text),
(316635,35182,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, normalmente les gusta el silencio, pero ahora ellas ... como locas.'::text,'están gritando'::text,'gritan'::text,NULL::text,'Qué va, tío, normalmente les gusta el silencio, pero ahora ellas están gritando como locas.'::text),
(316634,35182,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, d''habitude elles aiment le silence, mais là elles ... comme des folles.'::text,'sont en train de hurler'::text,'hurlent'::text,NULL::text,'Nan frérot, d''habitude elles aiment le silence, mais là elles sont en train de hurler comme des folles.'::text),
(316637,35182,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, genelde sessizliği severler ama şimdi deli gibi ...'::text,'çığlık atıyorlar'::text,'çığlık atarlar'::text,NULL::text,'Yok kanka, genelde sessizliği severler ama şimdi deli gibi çığlık atıyorlar.'::text),
(316638,35182,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, általában szeretik a csendet, de most úgy ..., mint az őrültek.'::text,'sikítanak'::text,'sikítanak'::text,NULL::text,'Á, tesó, általában szeretik a csendet, de most úgy sikítanak, mint az őrültek.'::text),
(316641,35183,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prognose: Die Stille ... heute Abend unter 1 Sekunde dauern.'::text,'wird'::text,'wird'::text,'dauernd'::text,'Prognose: Die Stille wird heute Abend unter 1 Sekunde dauern.'::text),
(316645,35183,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прогноз: тиша сьогодні ввечері ... менше 1 секунди.'::text,'триватиме'::text,'триватиме'::text,'триваючи'::text,'Прогноз: тиша сьогодні ввечері триватиме менше 1 секунди.'::text),
(316644,35183,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Previsión: el silencio ... menos de 1 segundo esta noche.'::text,'durará'::text,'durará'::text,'durando'::text,'Previsión: el silencio durará menos de 1 segundo esta noche.'::text),
(316643,35183,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prévision : le silence ... moins d''1 seconde ce soir.'::text,'durera'::text,'durera'::text,'durant'::text,'Prévision : le silence durera moins d''1 seconde ce soir.'::text),
(316646,35183,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin: sessizlik bu gece 1 saniyeden az ...'::text,'sürecek'::text,'sürecek'::text,'sürerek'::text,'Tahmin: sessizlik bu gece 1 saniyeden az sürecek.'::text),
(316647,35183,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Előrejelzés: a csend ma este 1 másodpercnél rövidebb ideig ...'::text,'fog tartani'::text,'fog tartani'::text,'tartva'::text,'Előrejelzés: a csend ma este 1 másodpercnél rövidebb ideig fog tartani.'::text),
(317019,35225,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist auf seinen Skiern sehr schnell, also ... er an der Kamera vorbeifahren.'::text,'wird'::text,'wird'::text,NULL::text,'Er ist auf seinen Skiern sehr schnell, also wird er an der Kamera vorbeifahren.'::text),
(317023,35225,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він дуже швидкий на лижах, тож він ... проїжджати повз камеру.'::text,'збирається'::text,'буде'::text,NULL::text,'Він дуже швидкий на лижах, тож він збирається проїжджати повз камеру.'::text),
(317022,35225,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es muy rápido con los esquís, así que él ... pasar junto a la cámara.'::text,'va a'::text,NULL::text,NULL::text,'Es muy rápido con los esquís, así que él va a pasar junto a la cámara.'::text),
(317021,35225,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est très rapide sur ses skis, donc il ... passer devant la caméra.'::text,'va'::text,NULL::text,NULL::text,'Il est très rapide sur ses skis, donc il va passer devant la caméra.'::text),
(317024,35225,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayaklarının üstünde çok hızlı, bu yüzden kameranın önünden ...'::text,'geçecek'::text,'geçecek'::text,NULL::text,'Kayaklarının üstünde çok hızlı, bu yüzden kameranın önünden geçecek.'::text),
(317025,35225,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon gyors a léceken, úgyhogy el ... haladni a kamera előtt.'::text,'fog'::text,'fog'::text,NULL::text,'Nagyon gyors a léceken, úgyhogy el fog haladni a kamera előtt.'::text),
(317028,35226,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, seine Ski wirbeln so viel ... auf, irgendwie Kult.'::text,'Schnee'::text,'Schnee'::text,'einen Schnee'::text,'Alter, seine Ski wirbeln so viel Schnee auf, irgendwie Kult.'::text),
(317032,35226,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, його лижі здіймають стільки ..., реально легендарно.'::text,'снігу'::text,'снігів'::text,'снігу'::text,'Бро, його лижі здіймають стільки снігу, реально легендарно.'::text),
(317031,35226,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, sus esquís levantan tanta ..., bastante icónico.'::text,'nieve'::text,'nieve'::text,'una nieve'::text,'Tío, sus esquís levantan tanta nieve, bastante icónico.'::text),
(317030,35226,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ses skis soulèvent tellement de ..., un peu iconique.'::text,'neige'::text,'neige'::text,'une neige'::text,'Frérot, ses skis soulèvent tellement de neige, un peu iconique.'::text),
(317033,35226,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kayakları o kadar çok ... savuruyor ki, epey efsane.'::text,'kar'::text,'karlar'::text,'bir kar'::text,'Kanka, kayakları o kadar çok kar savuruyor ki, epey efsane.'::text),
(317034,35226,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a lécei annyi ... vernek fel, elég ikonikus.'::text,'havat'::text,'havat'::text,'egy havat'::text,'Tesó, a lécei annyi havat vernek fel, elég ikonikus.'::text),
(317037,35227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, so ... Skifahrer auf der Piste, man muss auf die Ski aufpassen.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Alter, so viele Skifahrer auf der Piste, man muss auf die Ski aufpassen.'::text),
(317041,35227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, так ... лижників на схилі, треба стежити за тими лижами.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Бро, так багато лижників на схилі, треба стежити за тими лижами.'::text),
(317040,35227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... esquiadores en la pista, cuidado con esos esquís.'::text,'muchos'::text,'mucho'::text,'cualquier'::text,'Tío, muchos esquiadores en la pista, cuidado con esos esquís.'::text),
(317039,35227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ... skieurs sur la piste, faut faire gaffe à ces skis.'::text,'beaucoup de'::text,'beaucoup de'::text,'n''importe quels'::text,'Frérot, beaucoup de skieurs sur la piste, faut faire gaffe à ces skis.'::text),
(317042,35227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, pistte o kadar ... kayakçı var ki, o kayaklara dikkat etmek lazım.'::text,'çok'::text,'çok'::text,'herhangi'::text,'Kanka, pistte o kadar çok kayakçı var ki, o kayaklara dikkat etmek lazım.'::text),
(317043,35227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, olyan ... síelő van a pályán, figyelni kell azokra a lécekre.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Tesó, olyan sok síelő van a pályán, figyelni kell azokra a lécekre.'::text),
(317055,35229,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ski gehören auf Schnee, also ... er auf dem Schnee bleiben.'::text,'muss'::text,'muss'::text,'sollte'::text,'Ski gehören auf Schnee, also muss er auf dem Schnee bleiben.'::text),
(317059,35229,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лижі — для снігу, тож він ... залишатися на снігу.'::text,'має'::text,'мусить'::text,'мав би'::text,'Лижі — для снігу, тож він має залишатися на снігу.'::text),
(317058,35229,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los esquís van sobre la nieve, así que él ... quedarse en la nieve.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Los esquís van sobre la nieve, así que él tiene que quedarse en la nieve.'::text),
(317057,35229,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les skis vont sur la neige, donc il ... rester sur la neige.'::text,'doit'::text,'doit'::text,'devrait'::text,'Les skis vont sur la neige, donc il doit rester sur la neige.'::text),
(317060,35229,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayaklar kar üstünde kullanılır, bu yüzden karın üstünde ...'::text,'kalmak zorunda'::text,'kalmalı'::text,'kalmalı'::text,'Kayaklar kar üstünde kullanılır, bu yüzden karın üstünde kalmak zorunda.'::text),
(317061,35229,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A léc a hóra való, úgyhogy a havon ... maradnia.'::text,'kell'::text,'kell'::text,'kellene'::text,'A léc a hóra való, úgyhogy a havon kell maradnia.'::text),
(317064,35230,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht gelogen, du fliegst auf diesen Skiern. Du ... Stunden geben.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Nicht gelogen, du fliegst auf diesen Skiern. Du solltest Stunden geben.'::text),
(317068,35230,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ти літаєш на цих лижах. Ти ... давати уроки.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Не брехатиму, ти літаєш на цих лижах. Ти мав би давати уроки.'::text),
(317067,35230,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, vuelas con esos esquís. Tú ... dar clases.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'No voy a mentir, vuelas con esos esquís. Tú deberías dar clases.'::text),
(317066,35230,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu voles sur ces skis. Tu ... donner des cours.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Je vais pas mentir, tu voles sur ces skis. Tu devrais donner des cours.'::text),
(317069,35230,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o kayaklarla uçuyorsun. Ders ...'::text,'vermelisin'::text,'vermelisin'::text,'vermelisin'::text,'Yalan yok, o kayaklarla uçuyorsun. Ders vermelisin.'::text),
(317070,35230,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, repülsz azokon a léceken. Órákat ... tartanod.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Nem hazudok, repülsz azokon a léceken. Órákat kellene tartanod.'::text),
(317073,35231,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deine Ski sind schnell, ... du bleibst so ruhig. Beeindruckend, ehrlich.'::text,'aber'::text,'also'::text,'weil'::text,'Deine Ski sind schnell, aber du bleibst so ruhig. Beeindruckend, ehrlich.'::text),
(317077,35231,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твої лижі швидкі, ... ти лишаєшся таким спокійним. Вражає, чесно.'::text,'але'::text,'тому'::text,'бо'::text,'Твої лижі швидкі, але ти лишаєшся таким спокійним. Вражає, чесно.'::text),
(317076,35231,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tus esquís son rápidos, ... tú te mantienes tan tranquilo. Impresionante, la verdad.'::text,'pero'::text,'así que'::text,'porque'::text,'Tus esquís son rápidos, pero tú te mantienes tan tranquilo. Impresionante, la verdad.'::text),
(317075,35231,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tes skis sont rapides, ... tu restes si calme. Impressionnant, franchement.'::text,'mais'::text,'donc'::text,'parce que'::text,'Tes skis sont rapides, mais tu restes si calme. Impressionnant, franchement.'::text),
(317078,35231,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayakların hızlı ... sen çok sakin kalıyorsun. Etkileyici, cidden.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Kayakların hızlı ama sen çok sakin kalıyorsun. Etkileyici, cidden.'::text),
(317079,35231,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A léceid gyorsak, ... te olyan nyugodt maradsz. Lenyűgöző, őszintén.'::text,'de'::text,'ezért'::text,'mert'::text,'A léceid gyorsak, de te olyan nyugodt maradsz. Lenyűgöző, őszintén.'::text),
(296967,32997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Ball in seinen Handschuh.'::text,'schaufelt'::text,'schaufeln'::text,'schaufelnd'::text,'Er schaufelt den Ball in seinen Handschuh.'::text),
(296971,32997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... м''яч у свою рукавицю.'::text,'підхоплює'::text,'підхоплювати'::text,'підхоплюючи'::text,'Він підхоплює м''яч у свою рукавицю.'::text),
(296970,32997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la pelota con su guante.'::text,'recoge'::text,'recoger'::text,'recogiendo'::text,'Él recoge la pelota con su guante.'::text),
(296969,32997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la balle dans son gant.'::text,'ramasse'::text,'ramasser'::text,'ramassant'::text,'Il ramasse la balle dans son gant.'::text),
(296972,32997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topu eldiveninin içine ...'::text,'alır'::text,'almak'::text,'alarak'::text,'Topu eldiveninin içine alır.'::text),
(296973,32997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a labdát a kesztyűjébe.'::text,'Felkapja'::text,'Felkapni'::text,'Felkapó'::text,'Felkapja a labdát a kesztyűjébe.'::text),
(296976,32998,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit dem Handschuh ... du alles fangen. Respekt.'::text,'kannst'::text,'kannst'::text,'kannst'::text,'Mit dem Handschuh kannst du alles fangen. Respekt.'::text),
(296980,32998,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З цією рукавицею ти ... зловити що завгодно. Респект.'::text,'можеш'::text,'можеш'::text,'можеш'::text,'З цією рукавицею ти можеш зловити що завгодно. Респект.'::text),
(296979,32998,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con ese guante tú ... atrapar cualquier cosa. Respeto.'::text,'puedes'::text,'puedes'::text,'puedes'::text,'Con ese guante tú puedes atrapar cualquier cosa. Respeto.'::text),
(296978,32998,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec ce gant, tu ... attraper n''importe quoi. Respect.'::text,'peux'::text,'peux'::text,'peux'::text,'Avec ce gant, tu peux attraper n''importe quoi. Respect.'::text),
(296981,32998,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O eldivenle her şeyi ... Saygılar.'::text,'yakalayabilirsin'::text,'yakalayabilirsin'::text,'yakalayabilirsin'::text,'O eldivenle her şeyi yakalayabilirsin Saygılar.'::text),
(296982,32998,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azzal a kesztyűvel bármit ... elkapni. Respekt.'::text,'tudsz'::text,'tudsz'::text,'tudsz'::text,'Azzal a kesztyűvel bármit tudsz elkapni. Respekt.'::text),
(296985,32999,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach dem Hechtsprung ist so ... Staub auf seinem Handschuh.'::text,'viel'::text,'viele'::text,'irgendwelcher'::text,'Nach dem Hechtsprung ist so viel Staub auf seinem Handschuh.'::text),
